INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(75969, 2605, 2302, '<td valign="top">Understandable to have this shot a bit out of focus - but if it was a little more clear it would get a better score.</td>', 'Understandable to have this shot a bit out of focus - but if it was a little more clear it would get a better score.', '2002-06-24 09:51:00.000000', NULL, 1),
(75970, 2605, 2152, '<td valign="top">There''s a good deal of JPEG compression here.  The file is only about 1/3 of what''s allowed and it lowers the quality of the photo considerably.</td>', 'There''s a good deal of JPEG compression here.  The file is only about 1/3 of what''s allowed and it lowers the quality of the photo considerably.', '2002-06-24 12:07:00.000000', NULL, 1),
(75971, 2605, 327, '<td valign="top">Bad blur....hand held? I really do like the perspective and the DOF in the photo. Kee</td>', 'Bad blur....hand held? I really do like the perspective and the DOF in the photo. Kee', '2002-06-24 18:01:00.000000', NULL, 1),
(75972, 2605, 1175, '<td valign="top">I get the feeling you believe life in the city is a long and wavy road.</td>', 'I get the feeling you believe life in the city is a long and wavy road.', '2002-06-24 18:19:00.000000', NULL, 1),
(75973, 2605, 772, '<td valign="top">This is a good showing of city life.  As for the overall quality of the image, I have a few minor issues.  Normally, making photographs through the window of an automobile adds some distortion to the image.  I don''t know if that was your intent with this photo or not.  It also normally casts some unwanted reflections.  Another problem with that is that it causes under exposure in some cases.  The colors look flat in this photo and need a little punch to really bring the photo to life... = 6 - jmsetzler</td>', 'This is a good showing of city life.  As for the overall quality of the image, I have a few minor issues.  Normally, making photographs through the window of an automobile adds some distortion to the image.  I don''t know if that was your intent with this photo or not.  It also normally casts some unwanted reflections.  Another problem with that is that it causes under exposure in some cases.  The colors look flat in this photo and need a little punch to really bring the photo to life... = 6 - jmsetzler', '2002-06-25 17:34:00.000000', NULL, 1),
(75974, 2605, 2337, '<td valign="top">Nice shot with some strong lines.  Something is missing that i can''t really put my finger on.  Maybe if you had waited for someone to be crossing the street?  I don''t know.  Nice shot all in all.</td>', 'Nice shot with some strong lines.  Something is missing that i can''t really put my finger on.  Maybe if you had waited for someone to be crossing the street?  I don''t know.  Nice shot all in all.', '2002-06-25 19:39:00.000000', NULL, 1),
(75975, 2605, 1944, '<td valign="top">This picture might have benifited from a little more saturation  and contrast. Also, I''m seeing some .jpg artifacts on  my monitor.</td>', 'This picture might have benifited from a little more saturation  and contrast. Also, I''m seeing some .jpg artifacts on  my monitor.', '2002-06-25 22:06:00.000000', NULL, 1),
(75976, 2605, 2111, '<td valign="top">what an unimaginatively shitty title</td>', 'what an unimaginatively shitty title', '2002-06-26 11:53:00.000000', NULL, 1),
(75977, 2605, 734, '<td valign="top">I might have tried this at dusk for a more dramtic look</td>', 'I might have tried this at dusk for a more dramtic look', '2002-06-27 14:01:00.000000', NULL, 1),
(75978, 2605, 2, '<td valign="top">This shot just seems pretty boring.  Suggestions to make this shot better:  shoot at a different time of day with more exciting lighting; shoot at a lower angle, to make it less documentary-style; stand in the middle of the road to get symmetry working for you.  Your JPEG compression is also pretty bad.. save a little higher quality.</td>', 'This shot just seems pretty boring.  Suggestions to make this shot better:  shoot at a different time of day with more exciting lighting; shoot at a lower angle, to make it less documentary-style; stand in the middle of the road to get symmetry working for you.  Your JPEG compression is also pretty bad.. save a little higher quality.', '2002-06-28 12:27:00.000000', NULL, 1),
(75979, 2605, 1005, '<td valign="top">Pretty nice shot.  I see little "brackets" around the threes, building, etc. guessing this is caused by sharpening, maybe.  If so, try just a little less.  I have also heard that saving the original JPG to TIFF format, prior to ANY alterations, then alter the shot and resave back to JPG helps with data loss (less data loss), which might help, too.<br/>Photo 8 City 8 total 8</td>', 'Pretty nice shot.  I see little "brackets" around the threes, building, etc. guessing this is caused by sharpening, maybe.  If so, try just a little less.  I have also heard that saving the original JPG to TIFF format, prior to ANY alterations, then alter the shot and resave back to JPG helps with data loss (less data loss), which might help, too.Photo 8 City 8 total 8', '2002-06-28 20:59:00.000000', NULL, 1),
(75980, 2605, 1808, '<td valign="top">From Brooklyn? NJ?</td>', 'From Brooklyn? NJ?', '2002-06-28 22:48:00.000000', NULL, 1),
(75981, 2605, 637, '<td valign="top">I was wondering.. what 2-way street would lead to the Empire State Building.  Then I saw the green street sign... Queens of course.  I should know.  I grew up in Queens (Corona).  After the challenge, please emai me l the exact street location.  I''m guessing Woodside/Sunnyside.... maybe Skilman Ave??? sjgleah</td>', 'I was wondering.. what 2-way street would lead to the Empire State Building.  Then I saw the green street sign... Queens of course.  I should know.  I grew up in Queens (Corona).  After the challenge, please emai me l the exact street location.  I''m guessing Woodside/Sunnyside.... maybe Skilman Ave??? sjgleah', '2002-06-29 11:55:00.000000', NULL, 1),
(75982, 2605, 1054, '<td valign="top">Good contribution, both image and title.</td>', 'Good contribution, both image and title.', '2002-06-29 21:50:00.000000', NULL, 1),
(75983, 2607, 2134, '<td valign="top">Wish I could see more of the kid in blue...</td>', 'Wish I could see more of the kid in blue...', '2002-06-24 01:42:00.000000', NULL, 1),
(75984, 2607, 811, '<td valign="top">Wish you had been on the other side of the tree, that kid with the shopping cart would have been hilarious.  Your colors are good, as is the focus.</td>', 'Wish you had been on the other side of the tree, that kid with the shopping cart would have been hilarious.  Your colors are good, as is the focus.', '2002-06-24 15:29:00.000000', NULL, 1),
(75985, 2607, 772, '<td valign="top">This is an interesting photo but I think i would like it much more if each of the kids was not so close to the edge of the framing... I know that you had no control over this... = 5 - jmsetzler</td>', 'This is an interesting photo but I think i would like it much more if each of the kids was not so close to the edge of the framing... I know that you had no control over this... = 5 - jmsetzler', '2002-06-24 17:09:00.000000', NULL, 1),
(75986, 2607, 327, '<td valign="top">Fun action.</td>', 'Fun action.', '2002-06-24 17:56:00.000000', NULL, 1),
(75987, 2607, 1944, '<td valign="top">Captures the mood you wanted. If I had to make any comment, I''d say the framing is a little tight. The shot would have ''breathed'' a little better if there had been slightly more room on the right.</td>', 'Captures the mood you wanted. If I had to make any comment, I''d say the framing is a little tight. The shot would have ''breathed'' a little better if there had been slightly more room on the right.', '2002-06-25 00:05:00.000000', NULL, 1),
(75988, 2607, 1831, '<td valign="top">IMHO, would have liked to have seen the kids faces. A show of expression can make a powerful message."6". Dogman.</td>', 'IMHO, would have liked to have seen the kids faces. A show of expression can make a powerful message."6". Dogman.', '2002-06-25 04:06:00.000000', NULL, 1),
(75989, 2607, 1882, '<td valign="top">Never been a real big fan of "back" shots.  I''m sure you could have gotten a much better capture.  However, the photo is sharp and clear.</td>', 'Never been a real big fan of "back" shots.  I''m sure you could have gotten a much better capture.  However, the photo is sharp and clear.', '2002-06-25 16:05:00.000000', NULL, 1),
