(76010, 2608, 2448, '<td valign="top">immediate reaction,i love this photo</td>', 'immediate reaction,i love this photo', '2002-06-27 23:56:00.000000', NULL, 1),
(76011, 2608, 1005, '<td valign="top">Fun shot.  I like the motion, very cool.  The lit shield on left almost appears as if it is in the fountain.  Photo 8 City 7 Total 8</td>', 'Fun shot.  I like the motion, very cool.  The lit shield on left almost appears as if it is in the fountain.  Photo 8 City 7 Total 8', '2002-06-28 18:47:00.000000', NULL, 1),
