(76014, 2608, 1, '<td valign="top">nice use of shutter, i could do without the bright light on the left .. it seems to distract.</td>', 'nice use of shutter, i could do without the bright light on the left .. it seems to distract.', '2002-06-30 18:08:00.000000', NULL, 1),
(76015, 2609, 2334, '<td valign="top">too many signs...</td>', 'too many signs...', '2002-06-24 10:06:00.000000', NULL, 1),
(76016, 2609, 2337, '<td valign="top">LoL, decisions, decisions...  This shot might have been helped by shooting when the sun hit the signs.  Or maybe even the sun on the church sign with the bar in shadow.  Of course it''s often hard to get the sun to pose.</td>', 'LoL, decisions, decisions...  This shot might have been helped by shooting when the sun hit the signs.  Or maybe even the sun on the church sign with the bar in shadow.  Of course it''s often hard to get the sun to pose.', '2002-06-24 10:26:00.000000', NULL, 1),
