(76154, 2627, 117, '<td valign="top">thanks</td>', 'thanks', '2002-07-01 16:51:00.000000', NULL, 0),
(76155, 2630, 1054, '<td valign="top">Excellent capture. I love the earthy tones, powerful lines, and impled motion og the turning car.</td>', 'Excellent capture. I love the earthy tones, powerful lines, and impled motion og the turning car.', '2002-06-24 01:54:00.000000', NULL, 1),
(76156, 2630, 2337, '<td valign="top">Nice lines.  A bit fuzzy.  It''s lacking something, but I''m not sure what.  Maybe brighter cars could have helped.</td>', 'Nice lines.  A bit fuzzy.  It''s lacking something, but I''m not sure what.  Maybe brighter cars could have helped.', '2002-06-24 10:46:00.000000', NULL, 1),
(76157, 2630, 327, '<td valign="top">Good shot just empty. Looks like it was taken after the bomb.  Wow unemployement must be high there or you took this on a weekend. Fine shot of the city, good color, clear photo. Kee</td>', 'Good shot just empty. Looks like it was taken after the bomb.  Wow unemployement must be high there or you took this on a weekend. Fine shot of the city, good color, clear photo. Kee', '2002-06-24 14:15:00.000000', NULL, 1),
(76158, 2630, 811, '<td valign="top">Nice saturated colors.  I think a different angle might have made it more interesting.</td>', 'Nice saturated colors.  I think a different angle might have made it more interesting.', '2002-06-24 15:21:00.000000', NULL, 1),
(76159, 2630, 2172, '<td valign="top">I very much like the fact that texture is very apparent throughout the photo. Very crisp. Excellent image quality.  Good work</td>', 'I very much like the fact that texture is very apparent throughout the photo. Very crisp. Excellent image quality.  Good work', '2002-06-24 21:27:00.000000', NULL, 1),
(76160, 2630, 1856, '<td valign="top">I really like this...needs more focus and I''m not sure you could get a perfect crop with the buildings.  7</td>', 'I really like this...needs more focus and I''m not sure you could get a perfect crop with the buildings.  7', '2002-06-25 11:10:00.000000', NULL, 1),
(76161, 2630, 570, '<td valign="top">good city, not much life</td>', 'good city, not much life', '2002-06-25 16:07:00.000000', NULL, 1),
(76162, 2630, 2111, '<td valign="top">excellent 6</td>', 'excellent 6', '2002-06-25 17:02:00.000000', NULL, 1),
(76163, 2630, 772, '<td valign="top">Very nice shot of the city buildings... the lone gunman in the lower left corner adds a nice touch to this image :)  I also see that you have captured a rare glimpse of the north carolina state flower in the lower right corner :)  Those are the rare pavement dwelling striped "trafficus barrellus" flowers... They are mainly indiginous to the sides of highways and other roads... good shot!  = 7 - jmsetzler</td>', 'Very nice shot of the city buildings... the lone gunman in the lower left corner adds a nice touch to this image :)  I also see that you have captured a rare glimpse of the north carolina state flower in the lower right corner :)  Those are the rare pavement dwelling striped "trafficus barrellus" flowers... They are mainly indiginous to the sides of highways and other roads... good shot!  = 7 - jmsetzler', '2002-06-25 23:09:00.000000', NULL, 1),
(76164, 2630, 1944, '<td valign="top">Nice city shot.</td>', 'Nice city shot.', '2002-06-26 00:55:00.000000', NULL, 1),
(76165, 2630, 2321, '<td valign="top">cool, at least this pic has the city in it, lol, i really like this one</td>', 'cool, at least this pic has the city in it, lol, i really like this one', '2002-06-28 01:08:00.000000', NULL, 1),
(76166, 2630, 1005, '<td valign="top">Nice shot.  A little dull, was this on a weekend?  Seems like a "quiet" street.  Photo 8 City 8 total 8</td>', 'Nice shot.  A little dull, was this on a weekend?  Seems like a "quiet" street.  Photo 8 City 8 total 8', '2002-06-28 21:06:00.000000', NULL, 1),
(76167, 2630, 637, '<td valign="top">The lone pedestrian contributes something "interesting" to an otherwise bland scene.</td>', 'The lone pedestrian contributes something "interesting" to an otherwise bland scene.', '2002-06-29 11:20:00.000000', NULL, 1),
(76168, 2630, 1, '<td valign="top">Nice shot.  You have quite a few elemnts in your frame -- very well done.</td>', 'Nice shot.  You have quite a few elemnts in your frame -- very well done.', '2002-06-30 17:33:00.000000', NULL, 1);
