(76351, 2647, 2111, '<td valign="top">ewe</td>', 'ewe', '2002-06-25 17:07:00.000000', NULL, 1),
(76352, 2647, 2199, '<td valign="top">Nice composition; like how you''ve framed the "city girl" with the blue on the bottom and yellow on the left. Has a real Twilight Zone feel to it.....nice.</td>', 'Nice composition; like how you''ve framed the "city girl" with the blue on the bottom and yellow on the left. Has a real Twilight Zone feel to it.....nice.', '2002-06-25 22:15:00.000000', NULL, 1),
(76353, 2647, 1005, '<td valign="top">Good shot, focus/framing/composition all really good, but a bit ho hum overall.  (It''s probably just me)  Photo 7 City 6 total 7</td>', 'Good shot, focus/framing/composition all really good, but a bit ho hum overall.  (It''s probably just me)  Photo 7 City 6 total 7', '2002-06-26 20:16:00.000000', NULL, 1),
(76354, 2647, 2448, '<td valign="top">no comment</td>', 'no comment', '2002-06-27 23:00:00.000000', NULL, 1),
(76355, 2647, 1037, '<td valign="top">This is really cool. Great sense of texture, kitsch, slight surrealism. The colours and lighting are nice.</td>', 'This is really cool. Great sense of texture, kitsch, slight surrealism. The colours and lighting are nice.', '2002-06-28 04:42:00.000000', NULL, 1),
