(76357, 2647, 573, '<td valign="top">Technical looks pretty good.  Composition and WOW factor need some work in my opinion.</td>', 'Technical looks pretty good.  Composition and WOW factor need some work in my opinion.', '2002-06-28 18:53:00.000000', NULL, 1),
(76358, 2647, 1054, '<td valign="top">A good shot that would be better if your subject weren''t centered.</td>', 'A good shot that would be better if your subject weren''t centered.', '2002-06-29 21:23:00.000000', NULL, 1),
(76359, 2647, 811, '<td valign="top">Interesting.  I like the colors.</td>', 'Interesting.  I like the colors.', '2002-06-30 00:17:00.000000', NULL, 1),
(76360, 2647, 255, '<td valign="top">cool picture-- nice framing--kind of eerie subject! :)  8--amitchell</td>', 'cool picture-- nice framing--kind of eerie subject! :)  8--amitchell', '2002-06-30 04:50:00.000000', NULL, 1),
(76361, 2647, 1, '<td valign="top">I guess I don''t understand it.  Doesn''t seem very city-ish to me.</td>', 'I guess I don''t understand it.  Doesn''t seem very city-ish to me.', '2002-06-30 17:29:00.000000', NULL, 1),
(76362, 2647, 1078, '<td valign="top">Interesting shot.  Think it could have been a little better if the head had been placed a little lower and toward the left of the frame (rule of thirds).  Saying that, I don''t know what''s out of the frame to the right, so it might not have been possible.  I just think it would have had a little more impact with a smaller margin of yellow on the left and a lsightly smaller one on the right with the rest of the background made up of the draperies/blinds.</td>', 'Interesting shot.  Think it could have been a little better if the head had been placed a little lower and toward the left of the frame (rule of thirds).  Saying that, I don''t know what''s out of the frame to the right, so it might not have been possible.  I just think it would have had a little more impact with a smaller margin of yellow on the left and a lsightly smaller one on the right with the rest of the background made up of the draperies/blinds.', '2002-06-30 19:59:00.000000', NULL, 1),
(76363, 2647, 641, '<td valign="top">Can''t believe it scored so low. Definitely deserved better than #98 on the list. This was one of my favorites.</td>', 'Can''t believe it scored so low. Definitely deserved better than #98 on the list. This was one of my favorites.', '2002-07-01 14:41:00.000000', NULL, 0),
(76364, 2649, 1959, '<td valign="top">Beautiful colours!  Very well composed.</td>', 'Beautiful colours!  Very well composed.', '2002-06-24 02:31:00.000000', NULL, 1),
(76365, 2649, 2216, '<td valign="top">beautiful!</td>', 'beautiful!', '2002-06-24 02:31:00.000000', NULL, 1),
(76366, 2649, 1877, '<td valign="top">Great photo!! 7</td>', 'Great photo!! 7', '2002-06-24 05:12:00.000000', NULL, 1),
(76367, 2649, 2337, '<td valign="top">I''ve always had problems shooting fireworks and can''t wait to see the technicals on this shot.  Horizon is a bit sloped.  At first I was going to say it missed topic a bit, but decided ''city life'' is an open question with many interputations.  Nice shot!</td>', 'I''ve always had problems shooting fireworks and can''t wait to see the technicals on this shot.  Horizon is a bit sloped.  At first I was going to say it missed topic a bit, but decided ''city life'' is an open question with many interputations.  Nice shot!', '2002-06-24 10:33:00.000000', NULL, 1),
(76368, 2649, 92, '<td valign="top">Beautiful !</td>', 'Beautiful !', '2002-06-24 10:50:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(76369, 2649, 1859, '<td valign="top">And it''s not even 4th of July yet.  Nice fireworks shot!  Love the projection of the fireworks from the source.</td>', 'And it''s not even 4th of July yet.  Nice fireworks shot!  Love the projection of the fireworks from the source.', '2002-06-24 11:04:00.000000', NULL, 1),
(76370, 2649, 2343, '<td valign="top">I love what you captured but I would have cropped out the bottom.</td>', 'I love what you captured but I would have cropped out the bottom.', '2002-06-24 12:22:00.000000', NULL, 1),
(76371, 2649, 593, '<td valign="top">wow - great shot</td>', 'wow - great shot', '2002-06-24 12:39:00.000000', NULL, 1),
(76372, 2649, 1779, '<td valign="top">nice...  : )</td>', 'nice...  : )', '2002-06-24 14:06:00.000000', NULL, 1),
(76373, 2649, 2172, '<td valign="top">Great!!!!  Everything - great.  I''m in awe.  Magnificant.</td>', 'Great!!!!  Everything - great.  I''m in awe.  Magnificant.', '2002-06-24 14:34:00.000000', NULL, 1),
(76374, 2649, 327, '<td valign="top">Hey fun shot! Well done. Could be a little more crisp. Kee</td>', 'Hey fun shot! Well done. Could be a little more crisp. Kee', '2002-06-24 16:08:00.000000', NULL, 1),
(76375, 2649, 1005, '<td valign="top">Wow, great angle for this shot.  Were in some kind of tall building?  Very steady, how many seconds?  This is just great.  I like incorporating the launch site, but out of curiousity, did you try a landscape shot above the city line (just fireworks)?  Photo 10 City 9 total 10</td>', 'Wow, great angle for this shot.  Were in some kind of tall building?  Very steady, how many seconds?  This is just great.  I like incorporating the launch site, but out of curiousity, did you try a landscape shot above the city line (just fireworks)?  Photo 10 City 9 total 10', '2002-06-24 16:59:00.000000', NULL, 1),
(76376, 2649, 734, '<td valign="top">excelent shot, i bet you ended up with a bunch great out takes</td>', 'excelent shot, i bet you ended up with a bunch great out takes', '2002-06-24 17:03:00.000000', NULL, 1),
(76377, 2649, 641, '<td valign="top">Yea.. now that''s a fireworks shot. The tilt has me confused though.</td>', 'Yea.. now that''s a fireworks shot. The tilt has me confused though.', '2002-06-24 17:09:00.000000', NULL, 1),
(76378, 2649, 2368, '<td valign="top">Very nice shot.  At what speed and aperture did you set your camera?  Did you place the camera on the tripod?<br/></td>', 'Very nice shot.  At what speed and aperture did you set your camera?  Did you place the camera on the tripod?', '2002-06-24 19:52:00.000000', NULL, 1),
(76379, 2649, 2195, '<td valign="top">excellent shot of fireworks. awesome!</td>', 'excellent shot of fireworks. awesome!', '2002-06-25 00:04:00.000000', NULL, 1),
