(76381, 2649, 2140, '<td valign="top">i love these photos</td>', 'i love these photos', '2002-06-25 10:17:00.000000', NULL, 1),
(76382, 2649, 312, '<td valign="top">this is a nice shot. i could see it on a calendar or something. nice focus and composition. well done.</td>', 'this is a nice shot. i could see it on a calendar or something. nice focus and composition. well done.', '2002-06-25 13:55:00.000000', NULL, 1),
