(76385, 2649, 2279, '<td valign="top">best firework shot ive seen in awhile</td>', 'best firework shot ive seen in awhile', '2002-06-25 18:42:00.000000', NULL, 1),
(76386, 2649, 47, '<td valign="top">unst</td>', 'unst', '2002-06-25 20:40:00.000000', NULL, 1),
(76387, 2649, 1454, '<td valign="top">Just loved it!!</td>', 'Just loved it!!', '2002-06-25 20:55:00.000000', NULL, 1),
(76388, 2649, 1856, '<td valign="top">Incredible photo!  I can''t wait for the Fourth.  9 (dock one because IMO it doesn''t portray city life).  **Brumos in BC?  I assume most people on this site are from the U.S. and associate fireworks with a national holiday (4th of July and Chinese New Year).  It may have helped with the dating questions and inferred lack of association with city life had your title had been a bit more explanitory.**  Hindsight''s 20-20.  You''ll have to forgive those of us Americans who are unworldly...we''re ''educated'' to be so (embarassing, but true).  Your submission deserves to do well regardless**  If this isn''t Brumos, please ignore my **message**  ; D</td>', 'Incredible photo!  I can''t wait for the Fourth.  9 (dock one because IMO it doesn''t portray city life).  **Brumos in BC?  I assume most people on this site are from the U.S. and associate fireworks with a national holiday (4th of July and Chinese New Year).  It may have helped with the dating questions and inferred lack of association with city life had your title had been a bit more explanitory.**  Hindsight''s 20-20.  You''ll have to forgive those of us Americans who are unworldly...we''re ''educated'' to be so (embarassing, but true).  Your submission deserves to do well regardless**  If this isn''t Brumos, please ignore my **message**  ; D', '2002-06-25 21:41:00.000000', NULL, 1),
(76389, 2649, 1944, '<td valign="top">Good fireworks shot. Nicely timed.</td>', 'Good fireworks shot. Nicely timed.', '2002-06-25 22:16:00.000000', NULL, 1),
(76390, 2649, 806, '<td valign="top">Wow! Aren''t you just awesome! Were you on top of a building for this? Great shot all around!</td>', 'Wow! Aren''t you just awesome! Were you on top of a building for this? Great shot all around!', '2002-06-26 00:04:00.000000', NULL, 1),
(76391, 2649, 1882, '<td valign="top">Great fireworks shot!  If you really took this photo during the week of the challenge, great job!  What celebration was this?  Too early for 4th of July.</td>', 'Great fireworks shot!  If you really took this photo during the week of the challenge, great job!  What celebration was this?  Too early for 4th of July.', '2002-06-26 10:28:00.000000', NULL, 1),
(76392, 2649, 1897, '<td valign="top">was this really taken during the challenge.</td>', 'was this really taken during the challenge.', '2002-06-26 18:13:00.000000', NULL, 1),
(76393, 2649, 1543, '<td valign="top">great!</td>', 'great!', '2002-06-26 19:14:00.000000', NULL, 1),
