(76397, 2649, 772, '<td valign="top">Very nice work!  I would love to have done fireworks myself but there were none happening in my city during the challenge week.  You are lucky to have been able to capture this shot :)  Good work!  This is one of my favorites this week = 10 - jmsetzler</td>', 'Very nice work!  I would love to have done fireworks myself but there were none happening in my city during the challenge week.  You are lucky to have been able to capture this shot :)  Good work!  This is one of my favorites this week = 10 - jmsetzler', '2002-06-28 12:43:00.000000', NULL, 1),
(76398, 2649, 1808, '<td valign="top">Nice!</td>', 'Nice!', '2002-06-28 23:07:00.000000', NULL, 1),
(76399, 2649, 1256, '<td valign="top">Love it! Fireworks shots are hard, too.</td>', 'Love it! Fireworks shots are hard, too.', '2002-06-29 17:08:00.000000', NULL, 1),
