(76528, 2657, 327, '<td valign="top">Cute title, inventive work. Fun. Little over compressed or over sharpened. Nice job.Kee</td>', 'Cute title, inventive work. Fun. Little over compressed or over sharpened. Nice job.Kee', '2002-06-24 18:15:00.000000', NULL, 1),
(76529, 2657, 772, '<td valign="top">This is an interesting concept of city life.. especially with the wires and the garbage cans... The colors are a little flat and there seems to be a decent amount of jpeg compression artifacts lingering around... the wires are not crisp... good effort though :) = 5 - jmsetzler</td>', 'This is an interesting concept of city life.. especially with the wires and the garbage cans... The colors are a little flat and there seems to be a decent amount of jpeg compression artifacts lingering around... the wires are not crisp... good effort though :) = 5 - jmsetzler', '2002-06-24 21:02:00.000000', NULL, 1),
(76530, 2657, 1446, '<td valign="top">The soft focus and telephone pole running right up the middle detract from this photo IMO.</td>', 'The soft focus and telephone pole running right up the middle detract from this photo IMO.', '2002-06-25 11:03:00.000000', NULL, 1),
(76531, 2657, 1882, '<td valign="top">A little overexposed at the top of the telephone pole.  Would have chosen some subjects with more color or more interest next time, IMO.</td>', 'A little overexposed at the top of the telephone pole.  Would have chosen some subjects with more color or more interest next time, IMO.', '2002-06-25 16:02:00.000000', NULL, 1),
(76532, 2657, 811, '<td valign="top">Normally, I don''t care for power lines, but in this shot, they give a really "urban" feel to the picture.  The colors seem kinda muted to me, so I would try either adjusting saturation or trying it in black adn white.</td>', 'Normally, I don''t care for power lines, but in this shot, they give a really "urban" feel to the picture.  The colors seem kinda muted to me, so I would try either adjusting saturation or trying it in black adn white.', '2002-06-25 18:20:00.000000', NULL, 1),
(76533, 2657, 1897, '<td valign="top">Very cluttered, with no point of interest  Is this a cheap camera?  Or to compressed?</td>', 'Very cluttered, with no point of interest  Is this a cheap camera?  Or to compressed?', '2002-06-26 14:30:00.000000', NULL, 1),
(76534, 2657, 1005, '<td valign="top">I don''t get the McBar reference in the title, is that the city name or the nearest street?  As far as an alley shot goes, this is pretty much it.  As for the question:  "would I hang this in my house?", no, not really.  Is it good enough to hang in a gallery, probably.  Is the bright spot in the upper center of the shot the sun?  (or haze?)  No matter.  Photo 7 City 7 total 7</td>', 'I don''t get the McBar reference in the title, is that the city name or the nearest street?  As far as an alley shot goes, this is pretty much it.  As for the question:  "would I hang this in my house?", no, not really.  Is it good enough to hang in a gallery, probably.  Is the bright spot in the upper center of the shot the sun?  (or haze?)  No matter.  Photo 7 City 7 total 7', '2002-06-26 19:41:00.000000', NULL, 1),
(76535, 2657, 2448, '<td valign="top">no comment</td>', 'no comment', '2002-06-27 23:05:00.000000', NULL, 1),
