INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(76569, 2659, 705, '<td valign="top">this one works, but I don''t know why.  it''s very city, and it''s captivating somehow.  good lines.</td>', 'this one works, but I don''t know why.  it''s very city, and it''s captivating somehow.  good lines.', '2002-06-25 19:13:00.000000', NULL, 1),
(76570, 2659, 772, '<td valign="top">This is a nice view of city life, but I can''t really say that the shot ''speaks'' to me.  There''s nothing wrong with the shot... it just doesn''t peak my interest - = 6 - jmsetzler</td>', 'This is a nice view of city life, but I can''t really say that the shot ''speaks'' to me.  There''s nothing wrong with the shot... it just doesn''t peak my interest - = 6 - jmsetzler', '2002-06-26 17:08:00.000000', NULL, 1),
(76571, 2659, 472, '<td valign="top">that''s a fun picture.  although it doesn''t really have like something really going on, so it''s sort of static.  i like the guy pointing to the sky though ..</td>', 'that''s a fun picture.  although it doesn''t really have like something really going on, so it''s sort of static.  i like the guy pointing to the sky though ..', '2002-06-26 20:36:00.000000', NULL, 1),
