(77150, 2695, 705, '<td valign="top">Nice capture of action.  Too much going on.</td>', 'Nice capture of action.  Too much going on.', '2002-06-25 19:12:00.000000', NULL, 1),
(77151, 2695, 806, '<td valign="top">Wow! Awesome shot! (I''m going to a game tomorrow night - and sitting next to the bull pen! - But I''m not talented enough to get a shot like this!) Clear, all american, city event, excellent composition. I like it.<br/></td>', 'Wow! Awesome shot! (I''m going to a game tomorrow night - and sitting next to the bull pen! - But I''m not talented enough to get a shot like this!) Clear, all american, city event, excellent composition. I like it.', '2002-06-25 23:51:00.000000', NULL, 1),
(77152, 2695, 2247, '<td valign="top">Nice action shot!  You''ve been practicing.  Keep it up!</td>', 'Nice action shot!  You''ve been practicing.  Keep it up!', '2002-06-26 15:24:00.000000', NULL, 1),
(77153, 2695, 772, '<td valign="top">very nice!  I wish i lived in a major league city... great shot... great job of catching the baseball in a nice area of contrast... = 8 - jmsetzler</td>', 'very nice!  I wish i lived in a major league city... great shot... great job of catching the baseball in a nice area of contrast... = 8 - jmsetzler', '2002-06-26 22:16:00.000000', NULL, 1),
(77154, 2695, 2221, '<td valign="top">very good shot! good motion blur and composition. interesting selection for "city life" but it works for me.<br/>photo 9, creativity 9, city life 8 = 9</td>', 'very good shot! good motion blur and composition. interesting selection for "city life" but it works for me.photo 9, creativity 9, city life 8 = 9', '2002-06-27 22:35:00.000000', NULL, 1),
(77155, 2695, 2456, '<td valign="top">great picture! But what does it have to do with city life...?</td>', 'great picture! But what does it have to do with city life...?', '2002-06-28 14:10:00.000000', NULL, 1),
(77156, 2695, 1005, '<td valign="top">Interesting motion shot, very fast!  Photo 8 City 8 total 8 swash</td>', 'Interesting motion shot, very fast!  Photo 8 City 8 total 8 swash', '2002-06-28 21:04:00.000000', NULL, 1),
(77157, 2695, 1808, '<td valign="top">...and if you know the exposure time and distance from pitcher to catcher, you can estimate the speed of the pitch... I like it.</td>', '...and if you know the exposure time and distance from pitcher to catcher, you can estimate the speed of the pitch... I like it.', '2002-06-28 22:44:00.000000', NULL, 1),
(77158, 2695, 1054, '<td valign="top">Baseball is definitely part of *my* city life.  Good capture!</td>', 'Baseball is definitely part of *my* city life.  Good capture!', '2002-06-29 21:53:00.000000', NULL, 1),
(77159, 2695, 1, '<td valign="top">A fasters hutter speed could''ve frozen the action -- something that I think could''ve benefited the shot.</td>', 'A fasters hutter speed could''ve frozen the action -- something that I think could''ve benefited the shot.', '2002-07-01 00:31:00.000000', NULL, 1),
(77160, 2696, 2334, '<td valign="top">very interesting how you have the whole perspective thing going on with the lamps, then you have the people, and the buildings too.</td>', 'very interesting how you have the whole perspective thing going on with the lamps, then you have the people, and the buildings too.', '2002-06-24 02:09:00.000000', NULL, 1),
(77161, 2696, 1907, '<td valign="top">bit blurry</td>', 'bit blurry', '2002-06-24 05:32:00.000000', NULL, 1),
(77162, 2696, 2337, '<td valign="top">Very nice strong lines!  a little fuzzy (Mono/tripod might have helped)  The only other thing I would change is maybe waiting for a more interesting (ie. colorful) subject to wander into the center.  The eye is drawn to the bike, but s/he is fuzzy far and dark.</td>', 'Very nice strong lines!  a little fuzzy (Mono/tripod might have helped)  The only other thing I would change is maybe waiting for a more interesting (ie. colorful) subject to wander into the center.  The eye is drawn to the bike, but s/he is fuzzy far and dark.', '2002-06-24 11:00:00.000000', NULL, 1),
(77163, 2696, 711, '<td valign="top">this looks like a scanned picture</td>', 'this looks like a scanned picture', '2002-06-24 12:50:00.000000', NULL, 1),
(77164, 2696, 1779, '<td valign="top">nice... but it seems a bit out of focus, no?</td>', 'nice... but it seems a bit out of focus, no?', '2002-06-24 13:02:00.000000', NULL, 1),
(77165, 2696, 2188, '<td valign="top">Oops; a pixel off on the right? Nice perspective with the chairs and lamps. But you knew that. I might have brigtened it a bit.</td>', 'Oops; a pixel off on the right? Nice perspective with the chairs and lamps. But you knew that. I might have brigtened it a bit.', '2002-06-24 14:12:00.000000', NULL, 1),
(77166, 2696, 811, '<td valign="top">I think if the existing colors were a little brighter, this picture might have a little more *pop*  I like the way the lightposts pull your eyes toward the center of the picture, and then the tallest building pulls your eyes up.</td>', 'I think if the existing colors were a little brighter, this picture might have a little more *pop*  I like the way the lightposts pull your eyes toward the center of the picture, and then the tallest building pulls your eyes up.', '2002-06-24 15:10:00.000000', NULL, 1),
(77167, 2696, 327, '<td valign="top">Wow. Looks like a scan.....? Wonderful shot, DOF is great. Good work. Kee</td>', 'Wow. Looks like a scan.....? Wonderful shot, DOF is great. Good work. Kee', '2002-06-24 18:04:00.000000', NULL, 1),
(77168, 2696, 2302, '<td valign="top">nice photo but I wish it was a bit more focused along the pier</td>', 'nice photo but I wish it was a bit more focused along the pier', '2002-06-24 18:42:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(77169, 2696, 2172, '<td valign="top">I like the composition - the rows of lights leading up to the pointed building.  Well done!  The only con I see is that maybe the texture of the walkway could be a little more defined.  Where in San Francisco is this?  Beautiful place.</td>', 'I like the composition - the rows of lights leading up to the pointed building.  Well done!  The only con I see is that maybe the texture of the walkway could be a little more defined.  Where in San Francisco is this?  Beautiful place.', '2002-06-24 18:58:00.000000', NULL, 1),
(77170, 2696, 2199, '<td valign="top">nice perspective......how did you process this to get that "old" look?</td>', 'nice perspective......how did you process this to get that "old" look?', '2002-06-24 21:17:00.000000', NULL, 1),
(77171, 2696, 1759, '<td valign="top">Looks like a post card, nice!</td>', 'Looks like a post card, nice!', '2002-06-24 22:35:00.000000', NULL, 1),
(77172, 2696, 772, '<td valign="top">very nice city life view... I bet this one would look nice at night too :) = 6 - jmsetzler</td>', 'very nice city life view... I bet this one would look nice at night too :) = 6 - jmsetzler', '2002-06-24 23:26:00.000000', NULL, 1),
(77173, 2696, 1944, '<td valign="top">Nice composition. I like the way the eye is led around the picture. You have two basic light levels in this picture however which would have been hard to manage within the rules of this challange. You couldn''t have lightened the background buildings much without blowing them out, but the darker colors of the brick building, trees, and lamp posts merge and the effect is to lessen the impact. You  might have been able to open up the exposure a stop though, which might have pulled the line of lamp posts visually out from the trees.</td>', 'Nice composition. I like the way the eye is led around the picture. You have two basic light levels in this picture however which would have been hard to manage within the rules of this challange. You couldn''t have lightened the background buildings much without blowing them out, but the darker colors of the brick building, trees, and lamp posts merge and the effect is to lessen the impact. You  might have been able to open up the exposure a stop though, which might have pulled the line of lamp posts visually out from the trees.', '2002-06-25 00:36:00.000000', NULL, 1),
(77174, 2696, 1856, '<td valign="top">I love the composition of this photo.  It looks really blurry to me though and I would have cropped the person/bag/whatever out of the lower left side.  This would be a winner without the blur...as is 7.  Good job!</td>', 'I love the composition of this photo.  It looks really blurry to me though and I would have cropped the person/bag/whatever out of the lower left side.  This would be a winner without the blur...as is 7.  Good job!', '2002-06-25 10:36:00.000000', NULL, 1),
(77175, 2696, 1454, '<td valign="top">Nice picture, but the resolution looks very bad...</td>', 'Nice picture, but the resolution looks very bad...', '2002-06-25 16:19:00.000000', NULL, 1),
(77176, 2696, 1037, '<td valign="top">Nice composition and colour.</td>', 'Nice composition and colour.', '2002-06-26 01:02:00.000000', NULL, 1),
(77177, 2696, 1882, '<td valign="top">Not very sharp.  It looks old.</td>', 'Not very sharp.  It looks old.', '2002-06-26 11:45:00.000000', NULL, 1),
(77178, 2696, 1585, '<td valign="top">Real nice. I love this city and I peed on that building once.</td>', 'Real nice. I love this city and I peed on that building once.', '2002-06-26 14:17:00.000000', NULL, 1),
(77179, 2696, 1897, '<td valign="top">interesting shot, as far as city scenics go, this is very good.</td>', 'interesting shot, as far as city scenics go, this is very good.', '2002-06-26 14:37:00.000000', NULL, 1),
(77180, 2696, 472, '<td valign="top">has a strange washed out quality, and a weird bluish color cast.  could be a little sharper.  nice shot.</td>', 'has a strange washed out quality, and a weird bluish color cast.  could be a little sharper.  nice shot.', '2002-06-26 20:49:00.000000', NULL, 1),
(77181, 2696, 2, '<td valign="top">This is so washed out, it looks like a bad scan.  You also have a border on the right, which is against site rules.</td>', 'This is so washed out, it looks like a bad scan.  You also have a border on the right, which is against site rules.', '2002-06-27 02:04:00.000000', NULL, 1),
(77182, 2696, 806, '<td valign="top">This would have been awesome if it was clear. Levels, sharpened or something too much?</td>', 'This would have been awesome if it was clear. Levels, sharpened or something too much?', '2002-06-27 11:12:00.000000', NULL, 1),
(77183, 2696, 2321, '<td valign="top">awsome!</td>', 'awsome!', '2002-06-28 01:10:00.000000', NULL, 1),
(77184, 2696, 2109, '<td valign="top">strange looking photo.. looks like it was scanned from an older photo</td>', 'strange looking photo.. looks like it was scanned from an older photo', '2002-06-28 15:27:00.000000', NULL, 1),
(77185, 2696, 1005, '<td valign="top">Maybe it''s just the digital nature of longer shots, but it doesn''t seem that clear.  I like the idea/framing, etc.  The lamp posts make in interesting effect, but on the whole......Photo 8 City 9 total 8</td>', 'Maybe it''s just the digital nature of longer shots, but it doesn''t seem that clear.  I like the idea/framing, etc.  The lamp posts make in interesting effect, but on the whole......Photo 8 City 9 total 8', '2002-06-28 16:40:00.000000', NULL, 1),
(77186, 2696, 1808, '<td valign="top">Looks like an old postcard. Nice angle.</td>', 'Looks like an old postcard. Nice angle.', '2002-06-28 22:50:00.000000', NULL, 1),
(77187, 2696, 637, '<td valign="top">I''d crop this image somehow to take away some of the boardwalk from the foreground.</td>', 'I''d crop this image somehow to take away some of the boardwalk from the foreground.', '2002-06-29 18:23:00.000000', NULL, 1),
(77188, 2696, 1054, '<td valign="top">Excellent use of leading lines!</td>', 'Excellent use of leading lines!', '2002-06-29 21:46:00.000000', NULL, 1),
(77189, 2696, 441, '<td valign="top">only 45Kb - you are allowed 150Kb which you need to use to challenge the ''big boys'' - voters are looking for quality - some before content!</td>', 'only 45Kb - you are allowed 150Kb which you need to use to challenge the ''big boys'' - voters are looking for quality - some before content!', '2002-06-30 17:56:00.000000', NULL, 1),
(77190, 2696, 1, '<td valign="top">The photo lacks a lot of detail that could the shot out.</td>', 'The photo lacks a lot of detail that could the shot out.', '2002-06-30 23:20:00.000000', NULL, 1),
(77191, 2696, 1061, '<td valign="top">Great, but it looks like a scanned image</td>', 'Great, but it looks like a scanned image', '2002-07-01 00:52:00.000000', NULL, 1),
(77192, 2696, 1707, '<td valign="top">Thanks for all the comments! Sorry about the poor quality that many have noted but being the first submission, I was trying to learn how all this works.  It was much easier taking the photograph than getting Photoshop Elements and uploading it to this Web site! It took me forever to figure out how to get the right size, width, height, etc. I actually did crop the photo but I also see that I played with it too much (the extra border).  Also I was  pushed for time on Sunday night, I didn''t take the care to make sure key elements were focused.  I took the photo near Fisherman''s Warf, but it''s not Pier 39,  a few piers before (sorry, I didn''t pay attention to the number.  I was all the way at the end of the pier when I did see how nicely lined up the posts were to the buildings, particularly the trianglar one.  I was also wishing the Pier to be such a bit longer.  Maybe I''ll try again in a boat.  Interestingly enough, there was another photographer there too but I was jealous of him because he had better equipment!  Just to ease another question that alarmed me!, NO it''s not an old postcard I scanned!  I really did take this photograph!</td>', 'Thanks for all the comments! Sorry about the poor quality that many have noted but being the first submission, I was trying to learn how all this works.  It was much easier taking the photograph than getting Photoshop Elements and uploading it to this Web site! It took me forever to figure out how to get the right size, width, height, etc. I actually did crop the photo but I also see that I played with it too much (the extra border).  Also I was  pushed for time on Sunday night, I didn''t take the care to make sure key elements were focused.  I took the photo near Fisherman''s Warf, but it''s not Pier 39,  a few piers before (sorry, I didn''t pay attention to the number.  I was all the way at the end of the pier when I did see how nicely lined up the posts were to the buildings, particularly the trianglar one.  I was also wishing the Pier to be such a bit longer.  Maybe I''ll try again in a boat.  Interestingly enough, there was another photographer there too but I was jealous of him because he had better equipment!  Just to ease another question that alarmed me!, NO it''s not an old postcard I scanned!  I really did take this photograph!', '2002-07-01 09:31:00.000000', NULL, 0),
(77193, 2697, 1779, '<td valign="top">nice...  : )</td>', 'nice...  : )', '2002-06-24 14:04:00.000000', NULL, 1),
(77194, 2697, 327, '<td valign="top">Humm, kind of country meets city! Nice looking horses and a good shot we just aren''t seeing enough of it. If this was taken from the side (not head on) we could see the wagon/buggy and maybe more of the area to show it''s inner city. I hope that makes sense to you. Not a bad shot at all. Kee</td>', 'Humm, kind of country meets city! Nice looking horses and a good shot we just aren''t seeing enough of it. If this was taken from the side (not head on) we could see the wagon/buggy and maybe more of the area to show it''s inner city. I hope that makes sense to you. Not a bad shot at all. Kee', '2002-06-24 14:12:00.000000', NULL, 1),
(77195, 2697, 2172, '<td valign="top">Nice photo.  Great image quality.  If I have to criticize, I only would say to make a tighter crop.  Overall good photo.</td>', 'Nice photo.  Great image quality.  If I have to criticize, I only would say to make a tighter crop.  Overall good photo.', '2002-06-24 14:42:00.000000', NULL, 1),
(77196, 2697, 1856, '<td valign="top">Love the composition (except the guy in the red jacket).  Seems like the colors are a bid subdued...maybe it''s just the overcast day.</td>', 'Love the composition (except the guy in the red jacket).  Seems like the colors are a bid subdued...maybe it''s just the overcast day.', '2002-06-25 10:56:00.000000', NULL, 1),
(77197, 2697, 2111, '<td valign="top">whats with the capitals</td>', 'whats with the capitals', '2002-06-25 16:51:00.000000', NULL, 1),
(77198, 2697, 705, '<td valign="top">Really nice.  Good framing, composition, focus, and timing.</td>', 'Really nice.  Good framing, composition, focus, and timing.', '2002-06-25 19:07:00.000000', NULL, 1),
(77199, 2697, 1037, '<td valign="top">Those horses are so beautiful. Well framed shot, capturing a lot of character.</td>', 'Those horses are so beautiful. Well framed shot, capturing a lot of character.', '2002-06-26 05:46:00.000000', NULL, 1),
(77200, 2697, 2247, '<td valign="top">Brilliant image.  Beautiful colors and contrast.  Lots of depth and details.  Keep it up!</td>', 'Brilliant image.  Beautiful colors and contrast.  Lots of depth and details.  Keep it up!', '2002-06-26 15:16:00.000000', NULL, 1),
(77201, 2697, 772, '<td valign="top">This is a nice shot, but I believe that a different angle and possibly a wider angle that includes some things other than the horses would provide a better relationship to the ''city life'' theme.  = 6 - jmsetzler</td>', 'This is a nice shot, but I believe that a different angle and possibly a wider angle that includes some things other than the horses would provide a better relationship to the ''city life'' theme.  = 6 - jmsetzler', '2002-06-26 17:10:00.000000', NULL, 1),
(77202, 2697, 472, '<td valign="top">good horse picture!</td>', 'good horse picture!', '2002-06-26 21:24:00.000000', NULL, 1),
(77203, 2697, 1707, '<td valign="top">good shot of the horses but maybe include the surroundings a bit more</td>', 'good shot of the horses but maybe include the surroundings a bit more', '2002-06-27 03:15:00.000000', NULL, 1),
(77204, 2697, 806, '<td valign="top">Beautiful picture if you''re photographing an animals challenge.</td>', 'Beautiful picture if you''re photographing an animals challenge.', '2002-06-27 10:46:00.000000', NULL, 1),
(77205, 2697, 1005, '<td valign="top">Pretty horsies!  (don''t step on me...)  Lovely shot, nothing really bad to critique, be happy!  Photo 9 City 8 total 8</td>', 'Pretty horsies!  (don''t step on me...)  Lovely shot, nothing really bad to critique, be happy!  Photo 9 City 8 total 8', '2002-06-27 20:54:00.000000', NULL, 1),
(77206, 2697, 1808, '<td valign="top">Sell this one to Budweiser.</td>', 'Sell this one to Budweiser.', '2002-06-28 22:56:00.000000', NULL, 1),
(77207, 2697, 1054, '<td valign="top">Nice shot, flawless composition.</td>', 'Nice shot, flawless composition.', '2002-06-30 14:25:00.000000', NULL, 1),
(77208, 2698, 1897, '<td valign="top">this is a city scape,this tells no story about city life.</td>', 'this is a city scape,this tells no story about city life.', '2002-06-24 03:14:00.000000', NULL, 1),
(77209, 2698, 889, '<td valign="top">Its a bit hazy for a good long distance photo. I had that problem almost all week too. Got a good city picture and then decided not to use it.</td>', 'Its a bit hazy for a good long distance photo. I had that problem almost all week too. Got a good city picture and then decided not to use it.', '2002-06-24 12:58:00.000000', NULL, 1),
(77210, 2698, 1779, '<td valign="top">nice... but it need a bit more of contrast, no?</td>', 'nice... but it need a bit more of contrast, no?', '2002-06-24 13:01:00.000000', NULL, 1),
(77211, 2698, 327, '<td valign="top">Nice color, composition, clear shot. Hate to see that smog since I''m just south of you!! Very nice catch of the little plane taking off. Kee</td>', 'Nice color, composition, clear shot. Hate to see that smog since I''m just south of you!! Very nice catch of the little plane taking off. Kee', '2002-06-24 13:41:00.000000', NULL, 1),
(77212, 2698, 2172, '<td valign="top">Wow, this shows so much - many different aspects of a city.  Well done!</td>', 'Wow, this shows so much - many different aspects of a city.  Well done!', '2002-06-24 21:40:00.000000', NULL, 1),
(77213, 2698, 772, '<td valign="top">this is a nice city life shot but it looks a little hot on the exposure... the colors are washed out... I think a shot like this done early in the morning would be nice :) = 6 - jmsetzler</td>', 'this is a nice city life shot but it looks a little hot on the exposure... the colors are washed out... I think a shot like this done early in the morning would be nice :) = 6 - jmsetzler', '2002-06-24 23:19:00.000000', NULL, 1),
(77214, 2698, 705, '<td valign="top">this is very flat.</td>', 'this is very flat.', '2002-06-25 19:12:00.000000', NULL, 1),
(77215, 2698, 1944, '<td valign="top">Nice view of Renton and Lake Washington. I do think however the photo would have benifited by one stop less exposure. It would have compensated for the haze and added a little color density. It does give the feeling of the area though.  I can almost feel the traffic on I405:)</td>', 'Nice view of Renton and Lake Washington. I do think however the photo would have benifited by one stop less exposure. It would have compensated for the haze and added a little color density. It does give the feeling of the area though.  I can almost feel the traffic on I405:)', '2002-06-25 22:11:00.000000', NULL, 1),
(77216, 2698, 2221, '<td valign="top">To me the photo is a bit too busy. There are just too many small things to look at, which the title ("... etc.") is also an indicator. The misty (?) weather is ok, because it creates a nice distance of the city in the background. But I don''t see much "Life" (or an intended abscence of it as in other photos)  or anything interesting going on.<br/>Photo 4, Creativity 4, City Life 4 = 4</td>', 'To me the photo is a bit too busy. There are just too many small things to look at, which the title ("... etc.") is also an indicator. The misty (?) weather is ok, because it creates a nice distance of the city in the background. But I don''t see much "Life" (or an intended abscence of it as in other photos)  or anything interesting going on.Photo 4, Creativity 4, City Life 4 = 4', '2002-06-27 21:39:00.000000', NULL, 1),
(77217, 2698, 1054, '<td valign="top">Nice capture of the skyline.</td>', 'Nice capture of the skyline.', '2002-06-30 12:24:00.000000', NULL, 1),
(77218, 2698, 811, '<td valign="top">The colors are really muted.  Was it a hazy day?  In my limited knowledge, there are filters that help correct for that for some cameras (of course I can''t find them for mine).  Playing with the saturation levels may help too.</td>', 'The colors are really muted.  Was it a hazy day?  In my limited knowledge, there are filters that help correct for that for some cameras (of course I can''t find them for mine).  Playing with the saturation levels may help too.', '2002-06-30 22:59:00.000000', NULL, 1),
(77219, 2698, 527, '<td valign="top">I know this area well.  I would have raised the Seattle horizon line quite a bit more and included more of down town Renton. Maybe a little more contrast as well.<br/><br/>8  -Tim<br/></td>', 'I know this area well.  I would have raised the Seattle horizon line quite a bit more and included more of down town Renton. Maybe a little more contrast as well.8  -Tim', '2002-06-30 23:52:00.000000', NULL, 1),
(77220, 2700, 693, '<td valign="top">Interesting, but the composition needs some work.... too many subjects in focus (ie. the pink wall, the building) ; thereby distracting the viewers eye from the true subject.</td>', 'Interesting, but the composition needs some work.... too many subjects in focus (ie. the pink wall, the building) ; thereby distracting the viewers eye from the true subject.', '2002-06-24 01:42:00.000000', NULL, 1),
(77221, 2700, 1907, '<td valign="top">???</td>', '???', '2002-06-24 05:18:00.000000', NULL, 1),
(77222, 2700, 711, '<td valign="top">HOW U KEEP THAT HAIR STYLE INSIDE THE WATER MAN!!!!<br/><br/>YOU CHEATER...heheh</td>', 'HOW U KEEP THAT HAIR STYLE INSIDE THE WATER MAN!!!!YOU CHEATER...heheh', '2002-06-24 13:01:00.000000', NULL, 1),
(77223, 2700, 1779, '<td valign="top">cool... i like the colors</td>', 'cool... i like the colors', '2002-06-24 13:58:00.000000', NULL, 1),
(77224, 2700, 2188, '<td valign="top">Sweet duality with the box thing on the right! I feel like that most days...<br/>Something about the angles is throwing me off; but I think I like it.</td>', 'Sweet duality with the box thing on the right! I feel like that most days...Something about the angles is throwing me off; but I think I like it.', '2002-06-24 14:14:00.000000', NULL, 1),
(77225, 2700, 2172, '<td valign="top">I don''t know what to say....can''t quite figure the guy out.  Aside from that, Great Colors!  Must be somewhere out West or Down South - definately not here on the East!  If I have to criticize, the only thing I see is that the windows of the structure are a little overexposed - but I hardly notice because there is so much more to look at.  Bravo!</td>', 'I don''t know what to say....can''t quite figure the guy out.  Aside from that, Great Colors!  Must be somewhere out West or Down South - definately not here on the East!  If I have to criticize, the only thing I see is that the windows of the structure are a little overexposed - but I hardly notice because there is so much more to look at.  Bravo!', '2002-06-24 16:12:00.000000', NULL, 1),
(77226, 2700, 2261, '<td valign="top">Funky!</td>', 'Funky!', '2002-06-24 16:53:00.000000', NULL, 1),
