(77328, 2705, 2172, '<td valign="top">Great!  Just enough blur, yet crisp all over.  good job</td>', 'Great!  Just enough blur, yet crisp all over.  good job', '2002-06-24 14:29:00.000000', NULL, 1),
(77329, 2705, 2188, '<td valign="top">Fantastic! Just a perfect shutter speed. I love the guy in bottom left looking up. Can''t wait to see the info for this shot. I want to take one like this.</td>', 'Fantastic! Just a perfect shutter speed. I love the guy in bottom left looking up. Can''t wait to see the info for this shot. I want to take one like this.', '2002-06-24 15:42:00.000000', NULL, 1),
(77330, 2705, 280, '<td valign="top">Damn that was my idea :) I just didnt have the time (or a location as nice as this) and wouldnt have done it as well as this, good job.</td>', 'Damn that was my idea :) I just didnt have the time (or a location as nice as this) and wouldnt have done it as well as this, good job.', '2002-06-24 17:05:00.000000', NULL, 1),
(77331, 2705, 92, '<td valign="top">WOW ! This is GREAT !  I love the busy action of this ! The colors and everything just work for this challenge ! My first and so far only 10:)</td>', 'WOW ! This is GREAT !  I love the busy action of this ! The colors and everything just work for this challenge ! My first and so far only 10:)', '2002-06-24 19:03:00.000000', NULL, 1),
(77332, 2705, 117, '<td valign="top">movement ruins a perfect picture too bad we can''t yell freeze nice shot</td>', 'movement ruins a perfect picture too bad we can''t yell freeze nice shot', '2002-06-24 19:35:00.000000', NULL, 1),
