(77334, 2705, 2079, '<td valign="top">Congratulations  This is the shot I tried for several days to accomplishINSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(77369, 2706, 2337, '<td valign="top">Nice shot!  Did you have to wait long for the bird to pose?  Could have been a bit sharper.  Was this taken handheld?</td>', 'Nice shot!  Did you have to wait long for the bird to pose?  Could have been a bit sharper.  Was this taken handheld?', '2002-06-24 11:04:00.000000', NULL, 1),
(77370, 2706, 2343, '<td valign="top">I like the comment on rural vs. urban boundaries.  Yet I found the composition a bit unordered.</td>', 'I like the comment on rural vs. urban boundaries.  Yet I found the composition a bit unordered.', '2002-06-24 12:20:00.000000', NULL, 1),
(77371, 2706, 1779, '<td valign="top">nice combination...</td>', 'nice combination...', '2002-06-24 13:04:00.000000', NULL, 1),
(77372, 2706, 772, '<td valign="top">The heron in the city is a nice capture :)  Is that a heron?  Hmmm... not sure.. I also think i would like this shot a little more if the color was punched up just a bit... = 6 - jmsetzler</td>', 'The heron in the city is a nice capture :)  Is that a heron?  Hmmm... not sure.. I also think i would like this shot a little more if the color was punched up just a bit... = 6 - jmsetzler', '2002-06-24 17:12:00.000000', NULL, 1),
(77373, 2706, 327, '<td valign="top">How nice for the Heron, pretty. Nice shot good composition.</td>', 'How nice for the Heron, pretty. Nice shot good composition.', '2002-06-24 17:52:00.000000', NULL, 1),
(77374, 2706, 2023, '<td valign="top">Great shot, where is this at?<br/></td>', 'Great shot, where is this at?', '2002-06-24 21:29:00.000000', NULL, 1),
(77375, 2706, 2172, '<td valign="top">Nice cropping; good image quality.  I like this very much.  I like the way it displays our intrusion upon nature.  Well done!</td>', 'Nice cropping; good image quality.  I like this very much.  I like the way it displays our intrusion upon nature.  Well done!', '2002-06-24 21:32:00.000000', NULL, 1),
(77376, 2706, 1944, '<td valign="top">This picture really does show a mood to me. I like it.</td>', 'This picture really does show a mood to me. I like it.', '2002-06-25 00:41:00.000000', NULL, 1),
(77377, 2706, 2352, '<td valign="top">Great contrasts!</td>', 'Great contrasts!', '2002-06-26 22:10:00.000000', NULL, 1),
(77378, 2706, 806, '<td valign="top">Nice idea. Shows another aspect of life in the city. The picture itself isn''t that appealing though. Sorry.</td>', 'Nice idea. Shows another aspect of life in the city. The picture itself isn''t that appealing though. Sorry.', '2002-06-27 09:52:00.000000', NULL, 1),
(77379, 2706, 1005, '<td valign="top">At first I didn''t think too much of this shot (slightly boring), then I found the Heron (I''m a sucker for ''em) and your score went way up!  Photo 9 City 9 total 9</td>', 'At first I didn''t think too much of this shot (slightly boring), then I found the Heron (I''m a sucker for ''em) and your score went way up!  Photo 9 City 9 total 9', '2002-06-27 20:34:00.000000', NULL, 1),
(77380, 2706, 1031, '<td valign="top">Nice heron!</td>', 'Nice heron!', '2002-06-28 03:34:00.000000', NULL, 1),
(77381, 2706, 1003, '<td valign="top">maybe better focus?</td>', 'maybe better focus?', '2002-06-28 10:58:00.000000', NULL, 1),
(77382, 2706, 2460, '<td valign="top">Great photo!</td>', 'Great photo!', '2002-06-28 17:55:00.000000', NULL, 1),
(77383, 2706, 1808, '<td valign="top">Nice contrast!</td>', 'Nice contrast!', '2002-06-28 23:13:00.000000', NULL, 1),
(77384, 2706, 637, '<td valign="top">Very interesting story story told by this image.  6 sjgleah</td>', 'Very interesting story story told by this image.  6 sjgleah', '2002-06-29 11:49:00.000000', NULL, 1),
(77385, 2706, 811, '<td valign="top">To me, the most interesting part of your picture is at the bottom.  While I think I understand that you were trying to put the tree in front of the tall building, a close up of the bird, if possible, would have been nice, also.</td>', 'To me, the most interesting part of your picture is at the bottom.  While I think I understand that you were trying to put the tree in front of the tall building, a close up of the bird, if possible, would have been nice, also.', '2002-06-29 15:30:00.000000', NULL, 1),
(77386, 2706, 1054, '<td valign="top">Good contrast of man against nature.</td>', 'Good contrast of man against nature.', '2002-06-30 14:25:00.000000', NULL, 1),
(77387, 2706, 1, '<td valign="top">Nicely captured, the title fits it perfectly.</td>', 'Nicely captured, the title fits it perfectly.', '2002-06-30 23:04:00.000000', NULL, 1),
(77388, 2706, 2221, '<td valign="top">I photographed something else when suddenly the heron appeared. I hadn''t much time taking pictures because he walked away after some time. I did some closeups but my camera doesn''t have such a good zoom and this one already was zoomed in quite a bit.<br/><br/>jmsetzler: Actually the building in the background was brightly orange. I decided to desaturate it and only leave the green to stress the contrast between the "oasis" and the city more.<br/><br/>myqyl: Yes it was taken handheld. I don''t own a tripod.<br/><br/>I also had to sharpen it quite a lot using the "unsharp mask" in Gimp. The original looked very "washed out". I struggled a lot with the moiree effect of the building in the background. That''s also why I chose "unsharp mask" instead of "sharpen". It had better results.<br/><br/>Many thanks for your comments. I didn''t expect such a high score but now I''m very happy with it :-)<br/></td>', 'I photographed something else when suddenly the heron appeared. I hadn''t much time taking pictures because he walked away after some time. I did some closeups but my camera doesn''t have such a good zoom and this one already was zoomed in quite a bit.jmsetzler: Actually the building in the background was brightly orange. I decided to desaturate it and only leave the green to stress the contrast between the "oasis" and the city more.myqyl: Yes it was taken handheld. I don''t own a tripod.I also had to sharpen it quite a lot using the "unsharp mask" in Gimp. The original looked very "washed out". I struggled a lot with the moiree effect of the building in the background. That''s also why I chose "unsharp mask" instead of "sharpen". It had better results.Many thanks for your comments. I didn''t expect such a high score but now I''m very happy with it :-)', '2002-07-01 08:21:00.000000', NULL, 0),
(77389, 2707, 2337, '<td valign="top">Nice lines.  It moved my eyes around.  A bit stark, but so are cities :)</td>', 'Nice lines.  It moved my eyes around.  A bit stark, but so are cities :)', '2002-06-24 10:18:00.000000', NULL, 1),
(77390, 2707, 2380, '<td valign="top">A well chosen caption ! good composition of the shot. liked it .</td>', 'A well chosen caption ! good composition of the shot. liked it .', '2002-06-24 11:45:00.000000', NULL, 1),
(77391, 2707, 1779, '<td valign="top">nice...  : )</td>', 'nice...  : )', '2002-06-24 14:07:00.000000', NULL, 1),
(77392, 2707, 2172, '<td valign="top">I like the angle vs the arrow.  Made my twist my head.  Good image quality.  You were able to take something that I''m sure no-one really notices and brought it to life.  Well-done</td>', 'I like the angle vs the arrow.  Made my twist my head.  Good image quality.  You were able to take something that I''m sure no-one really notices and brought it to life.  Well-done', '2002-06-24 14:53:00.000000', NULL, 1),
(77393, 2707, 327, '<td valign="top">Kind of creepy. Trolls! &amp;lt;g&amp;gt; Nice shot and really on topic. Well done. Kee.</td>', 'Kind of creepy. Trolls! &lt;g&gt; Nice shot and really on topic. Well done. Kee.', '2002-06-24 16:24:00.000000', NULL, 1),
(77394, 2707, 1175, '<td valign="top">This does not convey city life to me.</td>', 'This does not convey city life to me.', '2002-06-24 18:18:00.000000', NULL, 1),
(77395, 2707, 117, '<td valign="top">interesting</td>', 'interesting', '2002-06-24 18:39:00.000000', NULL, 1),
(77396, 2707, 1877, '<td valign="top">Interesting concept/idea.. but I was looking forward to seeing more life within the city.. 5 for effort. :)</td>', 'Interesting concept/idea.. but I was looking forward to seeing more life within the city.. 5 for effort. :)', '2002-06-25 00:27:00.000000', NULL, 1),
(77397, 2707, 1944, '<td valign="top">I like the idea of this photo very much. The only things I could say against it is that I think it should have been framed a little looser in order to get in the whole casting, and it would have been nice if the color was a little darker and more saturated. I subtract 1 for each = 8.</td>', 'I like the idea of this photo very much. The only things I could say against it is that I think it should have been framed a little looser in order to get in the whole casting, and it would have been nice if the color was a little darker and more saturated. I subtract 1 for each = 8.', '2002-06-25 22:23:00.000000', NULL, 1),
(77398, 2707, 1897, '<td valign="top">Interesting abstract, seems more like on the road than "city life"</td>', 'Interesting abstract, seems more like on the road than "city life"', '2002-06-26 14:33:00.000000', NULL, 1),
(77399, 2707, 472, '<td valign="top">interesting idea. reminds me of a treasure map.  something about it just doesnt grab me, though.</td>', 'interesting idea. reminds me of a treasure map.  something about it just doesnt grab me, though.', '2002-06-26 16:47:00.000000', NULL, 1),
(77400, 2707, 772, '<td valign="top">This is a neat photo :)  I love a strong diagonal and this works for me.  I''m not really sure of your intentions or meaning on this photo, but it gets a 7 anyway :) - jmsetzler</td>', 'This is a neat photo :)  I love a strong diagonal and this works for me.  I''m not really sure of your intentions or meaning on this photo, but it gets a 7 anyway :) - jmsetzler', '2002-06-26 21:05:00.000000', NULL, 1),
(77401, 2707, 806, '<td valign="top">Nice idea about a city, but not about city life. (IMO). Sorry.</td>', 'Nice idea about a city, but not about city life. (IMO). Sorry.', '2002-06-27 10:26:00.000000', NULL, 1),
(77402, 2707, 1005, '<td valign="top">Well taken photo, but not interesting, to me.  Was there some emotion/feeling you were trying to express (that I obviously missed)?  Photo 7 City 5 total 6</td>', 'Well taken photo, but not interesting, to me.  Was there some emotion/feeling you were trying to express (that I obviously missed)?  Photo 7 City 5 total 6', '2002-06-27 18:28:00.000000', NULL, 1),
