(77409, 2709, 1779, '<td valign="top">very nice...  : )</td>', 'very nice...  : )', '2002-06-24 13:47:00.000000', NULL, 1),
(77410, 2709, 811, '<td valign="top">Nice use of colors (even if they weren''t your choice:-)) and I like the way you included the artist''s leg.  It gives the picture character and a sense of realness.</td>', 'Nice use of colors (even if they weren''t your choice:-)) and I like the way you included the artist''s leg.  It gives the picture character and a sense of realness.', '2002-06-24 15:02:00.000000', NULL, 1),
(77411, 2709, 2188, '<td valign="top">Fun. I would have liked to see more of the people watcing this I think.</td>', 'Fun. I would have liked to see more of the people watcing this I think.', '2002-06-24 15:40:00.000000', NULL, 1),
(77412, 2709, 327, '<td valign="top">I love these sidewalk artist. Don''t know where you took this but in Philly there are some really good one. This is wonderful and live the colors.Very good job, good representation of city life. Kee</td>', 'I love these sidewalk artist. Don''t know where you took this but in Philly there are some really good one. This is wonderful and live the colors.Very good job, good representation of city life. Kee', '2002-06-24 16:10:00.000000', NULL, 1),
(77413, 2709, 2172, '<td valign="top">Great "art work" haha.  Very nice pic.  This very much speaks for itself. Terrific.</td>', 'Great "art work" haha.  Very nice pic.  This very much speaks for itself. Terrific.', '2002-06-24 16:14:00.000000', NULL, 1),
(77414, 2709, 2337, '<td valign="top">I like this alot, although I can''t say why... It ''grabbed'' me.  The cropping on the box at the bottom was a little distracting, but all in all, I just plain like this one.</td>', 'I like this alot, although I can''t say why... It ''grabbed'' me.  The cropping on the box at the bottom was a little distracting, but all in all, I just plain like this one.', '2002-06-24 16:27:00.000000', NULL, 1),
