INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(77569, 2718, 327, '<td valign="top">Sorry the top of the building was cut off. Darn,.. but this is still a fun interesting shot. Kee.</td>', 'Sorry the top of the building was cut off. Darn,.. but this is still a fun interesting shot. Kee.', '2002-06-24 16:33:00.000000', NULL, 1),
(77570, 2718, 203, '<td valign="top">Is that the modern leaning tower of Piza?</td>', 'Is that the modern leaning tower of Piza?', '2002-06-24 16:57:00.000000', NULL, 1),
(77571, 2718, 2302, '<td valign="top">the building looks like it is leaning just a bit - I am not sure if rotating it would have caused the fire hydrant to lean instead though. nice colors - I like the clouds reflected in the glass</td>', 'the building looks like it is leaning just a bit - I am not sure if rotating it would have caused the fire hydrant to lean instead though. nice colors - I like the clouds reflected in the glass', '2002-06-24 18:38:00.000000', NULL, 1),
(77572, 2718, 117, '<td valign="top">I like the color mixture</td>', 'I like the color mixture', '2002-06-24 19:21:00.000000', NULL, 1),
(77573, 2718, 2172, '<td valign="top">I like it - the title too (witty)  I was going to do a USPS mail box, but this is better.  Great Job!</td>', 'I like it - the title too (witty)  I was going to do a USPS mail box, but this is better.  Great Job!', '2002-06-24 19:29:00.000000', NULL, 1),
(77574, 2718, 1204, '<td valign="top">Nice idea - perfect execution.  Good framing.</td>', 'Nice idea - perfect execution.  Good framing.', '2002-06-24 20:00:00.000000', NULL, 1),
(77575, 2718, 2158, '<td valign="top">Wonderful.</td>', 'Wonderful.', '2002-06-24 20:43:00.000000', NULL, 1),
(77576, 2718, 1759, '<td valign="top">An interesting contrast of shapes.</td>', 'An interesting contrast of shapes.', '2002-06-24 22:38:00.000000', NULL, 1),
(77577, 2718, 1856, '<td valign="top">Great colors and dof.  Two wishes...1) I wish the electric company would move that green box 2) I wish the building in the background was on a crooked foundation so it and the hydrant would be standing at the same angle.  9</td>', 'Great colors and dof.  Two wishes...1) I wish the electric company would move that green box 2) I wish the building in the background was on a crooked foundation so it and the hydrant would be standing at the same angle.  9', '2002-06-24 23:29:00.000000', NULL, 1),
(77578, 2718, 1944, '<td valign="top">Good idea. Very strong colors and powerful composition.</td>', 'Good idea. Very strong colors and powerful composition.', '2002-06-25 00:47:00.000000', NULL, 1),
(77579, 2718, 1143, '<td valign="top">I like the colors and juxtaposition. The tilting building is all that bothers me here. Great sky.</td>', 'I like the colors and juxtaposition. The tilting building is all that bothers me here. Great sky.', '2002-06-25 02:34:00.000000', NULL, 1),
(77580, 2718, 2337, '<td valign="top">Great use of color.  The building looks like it''s falling over though.  It''s hard to keep the horizon level in a shot like this, but it''s worth the effort :)</td>', 'Great use of color.  The building looks like it''s falling over though.  It''s hard to keep the horizon level in a shot like this, but it''s worth the effort :)', '2002-06-25 10:38:00.000000', NULL, 1),
(77581, 2718, 734, '<td valign="top">excelent colors,.. and a great angle... ths shot says allot.</td>', 'excelent colors,.. and a great angle... ths shot says allot.', '2002-06-25 15:05:00.000000', NULL, 1),
(77582, 2718, 1882, '<td valign="top">I would have liked it better if the top of the building had not been cropped.  But a cool shot nontheless.</td>', 'I would have liked it better if the top of the building had not been cropped.  But a cool shot nontheless.', '2002-06-26 10:48:00.000000', NULL, 1),
(77583, 2718, 2247, '<td valign="top">Nice perpective.  Beautiful color.  I love the angle you took this from.</td>', 'Nice perpective.  Beautiful color.  I love the angle you took this from.', '2002-06-26 15:43:00.000000', NULL, 1),
(77584, 2718, 472, '<td valign="top">i like it!  good juxta position....</td>', 'i like it!  good juxta position....', '2002-06-26 21:50:00.000000', NULL, 1),
(77585, 2718, 806, '<td valign="top">But does this show me what it is like to live in a city? Or take part in events of city life?</td>', 'But does this show me what it is like to live in a city? Or take part in events of city life?', '2002-06-27 10:35:00.000000', NULL, 1),
