(77697, 2723, 885, '<td valign="top">Neat subject.  The angle works well.</td>', 'Neat subject.  The angle works well.', '2002-06-26 09:51:00.000000', NULL, 1),
(77698, 2723, 472, '<td valign="top">i love this image. one of the best in the challenge. the link to city life seems tenuous, though.</td>', 'i love this image. one of the best in the challenge. the link to city life seems tenuous, though.', '2002-06-26 20:47:00.000000', NULL, 1),
(77699, 2723, 1037, '<td valign="top">Awesome work! This makes a really interesting statement about the visual life of a city.</td>', 'Awesome work! This makes a really interesting statement about the visual life of a city.', '2002-06-27 02:49:00.000000', NULL, 1),
(77700, 2723, 806, '<td valign="top">Transitions was a different challenge! Sorry. I''m sure you''ve heard that one. ... just a joke. Anyway.... Great photo, but it doesn''t say city life to me. Someone holding this sign, or a group of people demonstrating would have been more effective in telling the story.</td>', 'Transitions was a different challenge! Sorry. I''m sure you''ve heard that one. ... just a joke. Anyway.... Great photo, but it doesn''t say city life to me. Someone holding this sign, or a group of people demonstrating would have been more effective in telling the story.', '2002-06-27 10:49:00.000000', NULL, 1),
(77701, 2723, 2221, '<td valign="top">interesting angle but i''m not sure if it makes the photo better in this case. when i rotate my head to the right then it looks even more interesting ;-) then the dark and a bit distracting background could be cropped out, too. porttrait format would be better then of course.<br/>photo 8, creativity 9, city life 7 = 8</td>', 'interesting angle but i''m not sure if it makes the photo better in this case. when i rotate my head to the right then it looks even more interesting ;-) then the dark and a bit distracting background could be cropped out, too. porttrait format would be better then of course.photo 8, creativity 9, city life 7 = 8', '2002-06-27 22:24:00.000000', NULL, 1),
(77702, 2723, 2, '<td valign="top">So far, my favorite of the week.  Wow... very nicely done.  This shot is very stunning and visually powerful.</td>', 'So far, my favorite of the week.  Wow... very nicely done.  This shot is very stunning and visually powerful.', '2002-06-28 12:32:00.000000', NULL, 1),
(77703, 2723, 1005, '<td valign="top">Very interesting shot.  The background almost looks B&amp;W, while the bearded face seems overly yellow, but I like it.  Photo 8 City 7 total 8</td>', 'Very interesting shot.  The background almost looks B&W, while the bearded face seems overly yellow, but I like it.  Photo 8 City 7 total 8', '2002-06-28 16:08:00.000000', NULL, 1),
(77704, 2723, 1808, '<td valign="top">Hard to tell what''s going on, but nice colors and interesting faces...</td>', 'Hard to tell what''s going on, but nice colors and interesting faces...', '2002-06-28 23:12:00.000000', NULL, 1),
(77705, 2723, 1054, '<td valign="top">Took me a moment to figure out what this was at first.  Well done!</td>', 'Took me a moment to figure out what this was at first.  Well done!', '2002-06-30 12:24:00.000000', NULL, 1),
(77706, 2723, 1, '<td valign="top">Not sure how all of this represents city life...</td>', 'Not sure how all of this represents city life...', '2002-06-30 14:21:00.000000', NULL, 1),
(77707, 2723, 1078, '<td valign="top">Like the way this gives the feel of a colorized black and white.  Not that you have any control over it, but I wish you could see a little bit more of the face on the older advert.  Interesting composition with nice lines.  I can''t really say I like it, but I can appreciate it -- if that makes sense.</td>', 'Like the way this gives the feel of a colorized black and white.  Not that you have any control over it, but I wish you could see a little bit more of the face on the older advert.  Interesting composition with nice lines.  I can''t really say I like it, but I can appreciate it -- if that makes sense.', '2002-06-30 18:13:00.000000', NULL, 1),
(77708, 2723, 2009, '<td valign="top">I love this one too. My thought was that this may have been reffering to a cultural as well as visual transition.  aelith</td>', 'I love this one too. My thought was that this may have been reffering to a cultural as well as visual transition.  aelith', '2002-07-01 02:53:00.000000', NULL, 0),
