(77739, 2725, 1856, '<td valign="top">Perfect title.  Beautiful girl...love the concentration and determination you captured.  I can''t tell if this needs a touch more saturation or focus...something''s just a little bit off around her face.  9</td>', 'Perfect title.  Beautiful girl...love the concentration and determination you captured.  I can''t tell if this needs a touch more saturation or focus...something''s just a little bit off around her face.  9', '2002-06-24 23:50:00.000000', NULL, 1),
(77740, 2725, 2337, '<td valign="top">crop lost the top of her head and the board... a bit back and this is a wonderful shot</td>', 'crop lost the top of her head and the board... a bit back and this is a wonderful shot', '2002-06-25 10:57:00.000000', NULL, 1),
(77741, 2725, 312, '<td valign="top">i think the cropping is a little too tight on this. i''d have liked to see the rest of her head and skateboard sneak in there. might give more of a sense of action, as well.</td>', 'i think the cropping is a little too tight on this. i''d have liked to see the rest of her head and skateboard sneak in there. might give more of a sense of action, as well.', '2002-06-25 13:25:00.000000', NULL, 1),
