INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(77769, 2726, 2221, '<td valign="top">good shot! excellent DOF. b&amp;w works good. maybe a bit overexposured but this somehow creates a feeling as if this photo is a "dream" (also because of the soft light).<br/>because of the black dress and sunglasses of the woman, she is the "center of interest" in the photo. dunno if that was intended but guessing from the title i think not ;-)<br/>unfortunatley it doesn''t speak to me on the matter of "city life". "day out"... is that in a garden somewhere outside the city where the stressed family relaxes? just guessing but i think the photo should tell me that...<br/>photo 9, creativity 8, city life 5 = 7</td>', 'good shot! excellent DOF. b&w works good. maybe a bit overexposured but this somehow creates a feeling as if this photo is a "dream" (also because of the soft light).because of the black dress and sunglasses of the woman, she is the "center of interest" in the photo. dunno if that was intended but guessing from the title i think not ;-)unfortunatley it doesn''t speak to me on the matter of "city life". "day out"... is that in a garden somewhere outside the city where the stressed family relaxes? just guessing but i think the photo should tell me that...photo 9, creativity 8, city life 5 = 7', '2002-06-27 23:03:00.000000', NULL, 1),
