(78158, 2747, 885, '<td valign="top">Neat expression.  Nice out of focus background.  Did you ask the guy to take his picture, or are you just that sneaky?  The colors are a little weird...that red spot on his face/neck/the bird is a bit distracting.  But I like this one.  I only have one major complaint.  Where''s the c***** j******??? ;-)</td>', 'Neat expression.  Nice out of focus background.  Did you ask the guy to take his picture, or are you just that sneaky?  The colors are a little weird...that red spot on his face/neck/the bird is a bit distracting.  But I like this one.  I only have one major complaint.  Where''s the c***** j******??? ;-)', '2002-06-24 11:57:00.000000', NULL, 1),
(78159, 2747, 711, '<td valign="top">nice color</td>', 'nice color', '2002-06-24 13:02:00.000000', NULL, 1),
(78160, 2747, 327, '<td valign="top">lol He''s starting to look like his bird. Love the idea of this shot, just a bit out of focus but it''s nice and the face is clear. Fun shot. Kee</td>', 'lol He''s starting to look like his bird. Love the idea of this shot, just a bit out of focus but it''s nice and the face is clear. Fun shot. Kee', '2002-06-24 14:09:00.000000', NULL, 1),
(78161, 2747, 705, '<td valign="top">Great mood in this photo; interesting subject; the human models skin looks waxy,and the color casts, which I assume is from the fluoro lights, are unappealing-digital, or physical filters would help, or some color work in photoshop.  Actually, the casts work on the bird, really, just not on the human.  Great framing, and the expression on the human is wonderful-you''ve really caught his affection for the bird.</td>', 'Great mood in this photo; interesting subject; the human models skin looks waxy,and the color casts, which I assume is from the fluoro lights, are unappealing-digital, or physical filters would help, or some color work in photoshop.  Actually, the casts work on the bird, really, just not on the human.  Great framing, and the expression on the human is wonderful-you''ve really caught his affection for the bird.', '2002-06-24 15:19:00.000000', NULL, 1),
(78162, 2747, 1175, '<td valign="top">Looks like you got a bit of motion blur, probably cause it was at night.  his face looks kinda plastic.  I like the colors though.</td>', 'Looks like you got a bit of motion blur, probably cause it was at night.  his face looks kinda plastic.  I like the colors though.', '2002-06-24 15:57:00.000000', NULL, 1),
(78163, 2747, 1005, '<td valign="top">Love that wierd neon lighting, very cool, plus the motion of the parrots wings.  Wow,  I mean that!  The colors in this are just toooo much.<br/>Photo 10 City 10 total 10</td>', 'Love that wierd neon lighting, very cool, plus the motion of the parrots wings.  Wow,  I mean that!  The colors in this are just toooo much.Photo 10 City 10 total 10', '2002-06-24 17:37:00.000000', NULL, 1),
(78164, 2747, 772, '<td valign="top">I really like the lighting on this photo... The blurred neons in the background are a nice touch and it almost looks like this subject is lit by some neons that are out of the frame.  The blur on the bird''s wing is just perfect for showing a little motion.  Great shot! = 8 - jmsetzler</td>', 'I really like the lighting on this photo... The blurred neons in the background are a nice touch and it almost looks like this subject is lit by some neons that are out of the frame.  The blur on the bird''s wing is just perfect for showing a little motion.  Great shot! = 8 - jmsetzler', '2002-06-24 19:30:00.000000', NULL, 1),
(78165, 2747, 1856, '<td valign="top">Great shot...he looks like his bird.  I like the pinkish light being cast on the pair. 8</td>', 'Great shot...he looks like his bird.  I like the pinkish light being cast on the pair. 8', '2002-06-24 23:40:00.000000', NULL, 1),
(78166, 2747, 2389, '<td valign="top">good one</td>', 'good one', '2002-06-25 00:43:00.000000', NULL, 1),
(78167, 2747, 1037, '<td valign="top">I love the colours and the little bit of blur on the bird''s wing. The man looks a little bit self-conscious, but I like the way he''s looking at the bird. Nice framing too.</td>', 'I love the colours and the little bit of blur on the bird''s wing. The man looks a little bit self-conscious, but I like the way he''s looking at the bird. Nice framing too.', '2002-06-25 07:42:00.000000', NULL, 1),
(78168, 2747, 715, '<td valign="top">I like the atmosphere of this picture caused by the reflection of the neon lights on the guy and his parrot and the compostion is great. The way they look at each other shows how they like each other and you captured that moment very wel!</td>', 'I like the atmosphere of this picture caused by the reflection of the neon lights on the guy and his parrot and the compostion is great. The way they look at each other shows how they like each other and you captured that moment very wel!', '2002-06-26 17:09:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(78169, 2747, 1031, '<td valign="top">Nice lighting/color...</td>', 'Nice lighting/color...', '2002-06-28 03:55:00.000000', NULL, 1),
(78170, 2747, 2, '<td valign="top">The lighting and excitement of this photo are really working for you, though the man''s face seems slightly out of focus.</td>', 'The lighting and excitement of this photo are really working for you, though the man''s face seems slightly out of focus.', '2002-06-28 12:25:00.000000', NULL, 1),
(78171, 2747, 1054, '<td valign="top">Nice composition.  Landscape orientation is a good choice to bring out the background.</td>', 'Nice composition.  Landscape orientation is a good choice to bring out the background.', '2002-06-29 20:56:00.000000', NULL, 1),
(78172, 2747, 472, '<td valign="top">thanks for the comments. . . <br/>I took a s**tload of pics for citylife, some of which would probably have done better.  However, I thought it was unusual enough to come across this guy with his cockatiel that I submitted this one.  Actually, I think he was gay, and he was in the middle of being picked up by this other guy, when I, like a big lug, interrupted their courtship by taking their pictures.  When he noticed me, I asked if it was OK, and he said sure.  Of course immediately after I stopped shooting, the bird spread it''s wings :P.  I then showed both  men the pics on the LCD, and they were both really excited and asked me a lot of questions.  All in all, I enjoyed this challenge more than prolly any other :)</td>', 'thanks for the comments. . . I took a s**tload of pics for citylife, some of which would probably have done better.  However, I thought it was unusual enough to come across this guy with his cockatiel that I submitted this one.  Actually, I think he was gay, and he was in the middle of being picked up by this other guy, when I, like a big lug, interrupted their courtship by taking their pictures.  When he noticed me, I asked if it was OK, and he said sure.  Of course immediately after I stopped shooting, the bird spread it''s wings :P.  I then showed both  men the pics on the LCD, and they were both really excited and asked me a lot of questions.  All in all, I enjoyed this challenge more than prolly any other :)', '2002-07-02 00:26:00.000000', NULL, 0),
(78173, 2747, 472, '<td valign="top">Oh yeah.. I think any blur is because it''s so dark and my shutter speed is quite slow, plus I''m shooting on the fly.</td>', 'Oh yeah.. I think any blur is because it''s so dark and my shutter speed is quite slow, plus I''m shooting on the fly.', '2002-07-02 00:28:00.000000', NULL, 0),
(78174, 2748, 2334, '<td valign="top">the smoke and the sun are interesting elements in this picture.</td>', 'the smoke and the sun are interesting elements in this picture.', '2002-06-24 02:14:00.000000', NULL, 1),
(78175, 2748, 1779, '<td valign="top">nice...</td>', 'nice...', '2002-06-24 13:10:00.000000', NULL, 1),
(78176, 2748, 2188, '<td valign="top">Looks very other-worldly.</td>', 'Looks very other-worldly.', '2002-06-24 14:40:00.000000', NULL, 1),
(78177, 2748, 811, '<td valign="top">Nice silhouette effect, but the smokestack seems a little tilted to the right to me.  Interesting colors.</td>', 'Nice silhouette effect, but the smokestack seems a little tilted to the right to me.  Interesting colors.', '2002-06-24 15:00:00.000000', NULL, 1),
(78178, 2748, 327, '<td valign="top">Fire in the sky. Nice shot.</td>', 'Fire in the sky. Nice shot.', '2002-06-24 16:17:00.000000', NULL, 1),
(78179, 2748, 2172, '<td valign="top">Really nice effective photo.  The coloring is soft and pleasing.  I think some forget about the industrial aspect of a city - which in many cases is the only aspect for some people.  Well Done.</td>', 'Really nice effective photo.  The coloring is soft and pleasing.  I think some forget about the industrial aspect of a city - which in many cases is the only aspect for some people.  Well Done.', '2002-06-24 19:25:00.000000', NULL, 1),
(78180, 2748, 1143, '<td valign="top">Love the colors. Works well as a silhouete.</td>', 'Love the colors. Works well as a silhouete.', '2002-06-25 02:26:00.000000', NULL, 1),
(78181, 2748, 2140, '<td valign="top">good photo, it even represents city life.<br/>well done!</td>', 'good photo, it even represents city life.well done!', '2002-06-25 10:20:00.000000', NULL, 1),
(78182, 2748, 1759, '<td valign="top">Nice!</td>', 'Nice!', '2002-06-25 20:19:00.000000', NULL, 1),
(78183, 2748, 2337, '<td valign="top">This shot took a few days to grow on me, but the more I look, the more I like it... I might have liked it better with a ''little'' detail in the building, but it''s certainly a great shot... I''m buming it up a point.</td>', 'This shot took a few days to grow on me, but the more I look, the more I like it... I might have liked it better with a ''little'' detail in the building, but it''s certainly a great shot... I''m buming it up a point.', '2002-06-26 16:28:00.000000', NULL, 1),
(78184, 2748, 772, '<td valign="top">Nice shot and nice job of underexposing this photo for effect... :) = 8 - jmsetzler</td>', 'Nice shot and nice job of underexposing this photo for effect... :) = 8 - jmsetzler', '2002-06-26 22:22:00.000000', NULL, 1),
(78185, 2748, 1005, '<td valign="top">Great colors and effect.  Sad to think it''s due to pollution.  I like the red halo around the sun, cool.  Shadowed buildings in the foreground are also nice.  (Where was this for the shadows challenge?)  Photo 9 City 8 total 8</td>', 'Great colors and effect.  Sad to think it''s due to pollution.  I like the red halo around the sun, cool.  Shadowed buildings in the foreground are also nice.  (Where was this for the shadows challenge?)  Photo 9 City 8 total 8', '2002-06-28 16:15:00.000000', NULL, 1),
(78186, 2748, 1256, '<td valign="top">Nice sillouette shot.</td>', 'Nice sillouette shot.', '2002-06-29 16:56:00.000000', NULL, 1),
(78187, 2748, 637, '<td valign="top">Nice image, but doesn''t tell me anything about "city life". 4 sjgleah</td>', 'Nice image, but doesn''t tell me anything about "city life". 4 sjgleah', '2002-06-29 18:28:00.000000', NULL, 1),
(78188, 2748, 1054, '<td valign="top">Very elegant and simple; a textbook example of the rule of thirds.</td>', 'Very elegant and simple; a textbook example of the rule of thirds.', '2002-06-29 20:36:00.000000', NULL, 1),
(78189, 2748, 2247, '<td valign="top">I love your "smog sunset"!  Sets off the the rest of the pic that is black very well.</td>', 'I love your "smog sunset"!  Sets off the the rest of the pic that is black very well.', '2002-06-29 22:56:00.000000', NULL, 1),
(78190, 2748, 1, '<td valign="top">Nice sillhouette</td>', 'Nice sillhouette', '2002-06-30 23:10:00.000000', NULL, 1),
(78191, 2749, 2091, '<td valign="top">Like the buildings in the background.</td>', 'Like the buildings in the background.', '2002-06-24 01:52:00.000000', NULL, 1),
(78192, 2749, 693, '<td valign="top">this image appears to be stretched vertically or compressed horizontally.</td>', 'this image appears to be stretched vertically or compressed horizontally.', '2002-06-24 02:13:00.000000', NULL, 1),
(78193, 2749, 1877, '<td valign="top">Great shot of life and the city! 7</td>', 'Great shot of life and the city! 7', '2002-06-24 05:16:00.000000', NULL, 1),
(78194, 2749, 2200, '<td valign="top">This really captures concept of city life. Image could show more action.</td>', 'This really captures concept of city life. Image could show more action.', '2002-06-24 11:51:00.000000', NULL, 1),
(78195, 2749, 711, '<td valign="top">ball is out of position</td>', 'ball is out of position', '2002-06-24 13:02:00.000000', NULL, 1),
(78196, 2749, 1154, '<td valign="top">Exactly what comes to mind when I think of city life</td>', 'Exactly what comes to mind when I think of city life', '2002-06-24 13:22:00.000000', NULL, 1),
(78197, 2749, 327, '<td valign="top">Good visual of citylife! Nice colors, action, DOF. Kee</td>', 'Good visual of citylife! Nice colors, action, DOF. Kee', '2002-06-24 14:00:00.000000', NULL, 1),
(78198, 2749, 1779, '<td valign="top">nice...  : )</td>', 'nice...  : )', '2002-06-24 14:10:00.000000', NULL, 1),
(78199, 2749, 1175, '<td valign="top">Good capture.  Another position might have been prefered.  Did you have a chance to take multiple pictures or were you forced to take 1 and run?  If you could have taken more you may have gotten some better shots.</td>', 'Good capture.  Another position might have been prefered.  Did you have a chance to take multiple pictures or were you forced to take 1 and run?  If you could have taken more you may have gotten some better shots.', '2002-06-24 16:08:00.000000', NULL, 1),
(78200, 2749, 2172, '<td valign="top">Seems a little distorted?  Was that intentional?  That aside, nice image quality.  The scene is accentuated with the large buildings in the back.  Good job</td>', 'Seems a little distorted?  Was that intentional?  That aside, nice image quality.  The scene is accentuated with the large buildings in the back.  Good job', '2002-06-24 16:32:00.000000', NULL, 1),
(78201, 2749, 2337, '<td valign="top">Really nice... Cropped a bit tight on the left side for my tastes, but real nice shot</td>', 'Really nice... Cropped a bit tight on the left side for my tastes, but real nice shot', '2002-06-24 16:59:00.000000', NULL, 1),
(78202, 2749, 1759, '<td valign="top">You caught the real thing! Good job!</td>', 'You caught the real thing! Good job!', '2002-06-24 19:48:00.000000', NULL, 1),
(78203, 2749, 2023, '<td valign="top">Great action shot.  Definately a winner.</td>', 'Great action shot.  Definately a winner.', '2002-06-24 21:32:00.000000', NULL, 1),
(78204, 2749, 2111, '<td valign="top">the basketball, man! ya cropped out the ball</td>', 'the basketball, man! ya cropped out the ball', '2002-06-25 16:38:00.000000', NULL, 1),
(78205, 2749, 554, '<td valign="top">1 of 5  10''s   good job</td>', '1 of 5  10''s   good job', '2002-06-25 23:35:00.000000', NULL, 1),
(78206, 2749, 1944, '<td valign="top">I like your subject very much. Your exposure and shot timing were also good. Unfornatually, when you resized your picture you didn''t maintain the aspect ratio, so it appears a little compressed horizontally.</td>', 'I like your subject very much. Your exposure and shot timing were also good. Unfornatually, when you resized your picture you didn''t maintain the aspect ratio, so it appears a little compressed horizontally.', '2002-06-26 00:57:00.000000', NULL, 1),
(78207, 2749, 2417, '<td valign="top">Nice pic but what''s with the stretched image? On purpose or not?</td>', 'Nice pic but what''s with the stretched image? On purpose or not?', '2002-06-26 01:00:00.000000', NULL, 1),
(78208, 2749, 1031, '<td valign="top">I like the lack of signs (helps with idea of "any city") and the sense of impending motion</td>', 'I like the lack of signs (helps with idea of "any city") and the sense of impending motion', '2002-06-27 17:13:00.000000', NULL, 1),
(78209, 2749, 573, '<td valign="top">Nice photo too bad they put those ugly utility poles in the background.</td>', 'Nice photo too bad they put those ugly utility poles in the background.', '2002-06-27 18:51:00.000000', NULL, 1),
(78210, 2749, 2321, '<td valign="top">this image is great, and it captures city life, its nice to see that some photographers got the subject correct,</td>', 'this image is great, and it captures city life, its nice to see that some photographers got the subject correct,', '2002-06-28 01:13:00.000000', NULL, 1),
(78211, 2749, 1037, '<td valign="top">Great photo for this challenge. You captured something a lot of people have struggled with. Strong in the areas of composition, action shot, and colours.</td>', 'Great photo for this challenge. You captured something a lot of people have struggled with. Strong in the areas of composition, action shot, and colours.', '2002-06-28 04:57:00.000000', NULL, 1),
(78212, 2749, 772, '<td valign="top">Good shot :) Inner city basketball is definitely a good choice of city life :) = 8 - jmsetzler</td>', 'Good shot :) Inner city basketball is definitely a good choice of city life :) = 8 - jmsetzler', '2002-06-28 12:38:00.000000', NULL, 1),
(78213, 2749, 1005, '<td valign="top">Nice photo, but the aspect seems wrong....Did you stretch this image (just a little)?  I like the clock tower reflection in the blue building, cool.<br/>Photo 8 City 8 total 8</td>', 'Nice photo, but the aspect seems wrong....Did you stretch this image (just a little)?  I like the clock tower reflection in the blue building, cool.Photo 8 City 8 total 8', '2002-06-28 17:40:00.000000', NULL, 1),
(78214, 2749, 1808, '<td valign="top">Good mix of action and "city life".</td>', 'Good mix of action and "city life".', '2002-06-28 22:58:00.000000', NULL, 1),
(78215, 2749, 811, '<td valign="top">This looks nice in color, but black and white or sepia looks cool too.  My only suggestion would be to have a horizontal frame so that there are more of the ball players.  The buildings provide a nice backdrop, but I think since the subject is the boys, it would be better not to crop their hands off.</td>', 'This looks nice in color, but black and white or sepia looks cool too.  My only suggestion would be to have a horizontal frame so that there are more of the ball players.  The buildings provide a nice backdrop, but I think since the subject is the boys, it would be better not to crop their hands off.', '2002-06-30 00:08:00.000000', NULL, 1),
(78216, 2749, 1054, '<td valign="top">Great capture.  If basketball isn''t city life, I don''t know what is.</td>', 'Great capture.  If basketball isn''t city life, I don''t know what is.', '2002-06-30 12:29:00.000000', NULL, 1),
(78217, 2749, 2221, '<td valign="top">Good "City Life" shot! Maybe if you zoomed out a little the left player wouldn''t be cropped. This would also show a little more of the surroundings and thus stressing the contrast between the city (skyscrapers) and the "life" (players) more.<br/>Photo 8, Creativity 7, City Life 10 = 8</td>', 'Good "City Life" shot! Maybe if you zoomed out a little the left player wouldn''t be cropped. This would also show a little more of the surroundings and thus stressing the contrast between the city (skyscrapers) and the "life" (players) more.Photo 8, Creativity 7, City Life 10 = 8', '2002-06-30 21:11:00.000000', NULL, 1),
(78218, 2749, 1, '<td valign="top">The only thing it''s missing is a more visible hoop and net.  I''d prefer to have the ball not cut off too.</td>', 'The only thing it''s missing is a more visible hoop and net.  I''d prefer to have the ball not cut off too.', '2002-06-30 23:21:00.000000', NULL, 1),
(78219, 2749, 1061, '<td valign="top">Looks stretched.. how''d that happen?</td>', 'Looks stretched.. how''d that happen?', '2002-07-01 00:43:00.000000', NULL, 1),
(78220, 2750, 2334, '<td valign="top">good angle</td>', 'good angle', '2002-06-24 01:54:00.000000', NULL, 1),
(78221, 2750, 2011, '<td valign="top">Isnt this FUN!!!</td>', 'Isnt this FUN!!!', '2002-06-24 03:15:00.000000', NULL, 1),
(78222, 2750, 1569, '<td valign="top">The exposure is a little off,but a nice dramatic pix.</td>', 'The exposure is a little off,but a nice dramatic pix.', '2002-06-24 10:04:00.000000', NULL, 1),
(78223, 2750, 641, '<td valign="top">I think I''d probably like to see the view up of just the building, not including the scaffolding. Also maybe play with the contrast a little, it seems a little dark.</td>', 'I think I''d probably like to see the view up of just the building, not including the scaffolding. Also maybe play with the contrast a little, it seems a little dark.', '2002-06-24 12:54:00.000000', NULL, 1),
(78224, 2750, 1779, '<td valign="top">nice... a few clouds and it would''ve been great : )</td>', 'nice... a few clouds and it would''ve been great : )', '2002-06-24 13:22:00.000000', NULL, 1),
(78225, 2750, 1175, '<td valign="top">Where is the life?</td>', 'Where is the life?', '2002-06-24 16:05:00.000000', NULL, 1),
(78226, 2750, 2302, '<td valign="top">the building looks like it has some interesting features as does the fire escape - with the two together I am not sure where to look.</td>', 'the building looks like it has some interesting features as does the fire escape - with the two together I am not sure where to look.', '2002-06-24 18:08:00.000000', NULL, 1),
(78227, 2750, 2337, '<td valign="top">Nice lines... A little on the dark side though.</td>', 'Nice lines... A little on the dark side though.', '2002-06-24 18:35:00.000000', NULL, 1),
(78228, 2750, 1759, '<td valign="top">I think the composition is good, but it looses a lot from being so under exposed.</td>', 'I think the composition is good, but it looses a lot from being so under exposed.', '2002-06-24 19:16:00.000000', NULL, 1),
(78229, 2750, 2172, '<td valign="top">Really nice.  I like that I can see the texture of the building.  Well done!</td>', 'Really nice.  I like that I can see the texture of the building.  Well done!', '2002-06-24 19:20:00.000000', NULL, 1),
(78230, 2750, 772, '<td valign="top">I love the perspective on this photo... It appears that the lighting is a little weak, however.  I think that this shot may have been more vibrant at a different time of day.  These colors look bright but the flat lighting isn''t highlighting them very well... = 6 - jmsetzler</td>', 'I love the perspective on this photo... It appears that the lighting is a little weak, however.  I think that this shot may have been more vibrant at a different time of day.  These colors look bright but the flat lighting isn''t highlighting them very well... = 6 - jmsetzler', '2002-06-24 19:24:00.000000', NULL, 1),
(78231, 2750, 1005, '<td valign="top">Very red (even the rope is red) and a bit hard to view.  Why this view of your city?  Photo 4 City 7 total 5</td>', 'Very red (even the rope is red) and a bit hard to view.  Why this view of your city?  Photo 4 City 7 total 5', '2002-06-24 20:19:00.000000', NULL, 1),
(78232, 2750, 1143, '<td valign="top">Love the angle. Seems a little underexposed.</td>', 'Love the angle. Seems a little underexposed.', '2002-06-25 02:36:00.000000', NULL, 1),
(78233, 2750, 1897, '<td valign="top">Good pic, does not meet the challenge</td>', 'Good pic, does not meet the challenge', '2002-06-26 18:26:00.000000', NULL, 1),
(78234, 2750, 806, '<td valign="top">Over sharpened? Over corrected? How about looking up to someone poking their head out the window here or in another building. People in the city are always "hanging" out the window and talking to others below.</td>', 'Over sharpened? Over corrected? How about looking up to someone poking their head out the window here or in another building. People in the city are always "hanging" out the window and talking to others below.', '2002-06-27 10:44:00.000000', NULL, 1),
(78235, 2750, 2158, '<td valign="top">Where''s the life in this photo?</td>', 'Where''s the life in this photo?', '2002-06-28 19:44:00.000000', NULL, 1),
(78236, 2750, 2, '<td valign="top">This shot seems way too dark and drab -- the red building would be awesome if it were bold and bright.</td>', 'This shot seems way too dark and drab -- the red building would be awesome if it were bold and bright.', '2002-06-29 17:17:00.000000', NULL, 1),
(78237, 2750, 637, '<td valign="top">Too dark for my taste.  3 sjgleah</td>', 'Too dark for my taste.  3 sjgleah', '2002-06-29 18:27:00.000000', NULL, 1),
