(78239, 2750, 1, '<td valign="top">Cool angle to show the construction platforms.  I''d prefer better lighting.</td>', 'Cool angle to show the construction platforms.  I''d prefer better lighting.', '2002-06-30 17:52:00.000000', NULL, 1),
(78240, 2750, 2481, '<td valign="top">Nice angle shot, good color - chose this because it showed "every city" and not one specific city.   The perspective is very dramatic.  Nice shot.</td>', 'Nice angle shot, good color - chose this because it showed "every city" and not one specific city.   The perspective is very dramatic.  Nice shot.', '2002-06-30 20:45:00.000000', NULL, 1),
