(78339, 2757, 1, '<td valign="top">Not too much detail exists, seems very blurry.</td>', 'Not too much detail exists, seems very blurry.', '2002-06-30 23:09:00.000000', NULL, 1),
(78340, 2757, 2172, '<td valign="top">Thanks for all of your comments.  I had trouble with the resampling and adjustments.  That''s ok, I''ve learned a lot since then.  I re-adjusted and I believe the photo came out much better.  Also, I did adjust the color balance a bit to enhance the contrasts the red brick and the green tops of the buildings.  The adjustments are in my gallery <a href="//www.pbase.com/redruthann" rel="nofollow" target="_blank">Gallery</a> <br/><br/>If anyone does take the time to check them out, I wouldn''t mind any comments.<br/><br/>Taken in NEW HAVEN, CT on top of a parking garage.</td>', 'Thanks for all of your comments.  I had trouble with the resampling and adjustments.  That''s ok, I''ve learned a lot since then.  I re-adjusted and I believe the photo came out much better.  Also, I did adjust the color balance a bit to enhance the contrasts the red brick and the green tops of the buildings.  The adjustments are in my gallery Gallery If anyone does take the time to check them out, I wouldn''t mind any comments.Taken in NEW HAVEN, CT on top of a parking garage.', '2002-07-01 11:46:00.000000', NULL, 0),
(78341, 2757, 1041, '<td valign="top">I just tried to check out your new version of the photo but couldn''t find it in your gallery.  Hm.  Which of your galleries did you put the photo in?</td>', 'I just tried to check out your new version of the photo but couldn''t find it in your gallery.  Hm.  Which of your galleries did you put the photo in?', '2002-07-01 12:04:00.000000', NULL, 0),
(78342, 2757, 2172, '<td valign="top">//www.pbase.com/redruthann/for_challenges<br/>Sorry - it''s in City Life<br/><br/>Thanks for checking!</td>', '//www.pbase.com/redruthann/for_challengesSorry - it''s in City LifeThanks for checking!', '2002-07-01 15:57:00.000000', NULL, 0),
